var documenterSearchIndex = {"docs":
[{"category":"section","location":"examples/04_chat/#Chat-Bidirectional-Streaming-RPC","page":"Chat","text":"This example demonstrates bidirectional streaming RPC, where both client and server can send multiple messages simultaneously.","title":"Chat - Bidirectional Streaming RPC"},{"category":"section","location":"examples/04_chat/#What-You'll-Learn","page":"Chat","text":"Defining a proto service with bidirectional streaming RPC\nImplementing a bidirectional handler using BidiStream{TIn, TOut}\nReceiving and sending messages concurrently\nProperly closing bidirectional streams","title":"What You'll Learn"},{"category":"section","location":"examples/04_chat/#Proto-Definition","page":"Chat","text":"// chat.proto\nsyntax = \"proto3\";\npackage chat;\n\nservice Chat {\n  // Bidirectional streaming: stream of requests ↔ stream of responses\n  rpc Chat (stream ChatMessage) returns (stream ChatMessage);\n}\n\nmessage ChatMessage {\n  string user = 1;\n  string text = 2;\n}\n\nThe stream keyword on BOTH request AND response indicates bidirectional streaming.","title":"Proto Definition"},{"category":"section","location":"examples/04_chat/#Server-Implementation","page":"Chat","text":"using gRPCServer\n\n# Include generated types\ninclude(\"generated/chat/chat.jl\")\nusing .chat\n\n# Bidirectional streaming handler - receives and sends multiple messages\nfunction chat_handler(ctx::ServerContext, stream::BidiStream{ChatMessage, ChatMessage})\n    @info \"Chat session started\" request_id=ctx.request_id\n\n    for message in stream\n        if is_cancelled(ctx)\n            @warn \"Chat cancelled by client\"\n            break\n        end\n\n        @info \"Received message\" user=message.user text=message.text\n\n        # Echo back with server prefix\n        response = ChatMessage(\"Server\", \"You said: $(message.text)\")\n        send!(stream, response)\n    end\n\n    close!(stream)\n    @info \"Chat session ended\" request_id=ctx.request_id\n    return nothing\nend\n\n# Register the service with the codegen registration function\nfunction main()\n    host = \"127.0.0.1\"\n    port = 50054\n    server = GRPCServer(host, port;\n        enable_health_check = true,\n        enable_reflection = true\n    )\n\n    register_Chat!(server; Chat = chat_handler)\n\n    @info \"gRPC server starting (bidirectional streaming example)\" host=host port=port\n    run(server)\nend\n\nmain()\n\nEquivalent form — the per-RPC do-block registration:\n\nregister_Chat_Chat!(server) do ctx, stream\n    for message in stream\n        send!(stream, ChatMessage(\"Server\", \"You said: $(message.text)\"))\n    end\n    close!(stream)\n    return nothing\nend","title":"Server Implementation"},{"category":"section","location":"examples/04_chat/#Key-Concepts","page":"Chat","text":"","title":"Key Concepts"},{"category":"section","location":"examples/04_chat/#Bidirectional-Handler-Signature","page":"Chat","text":"function handler(ctx::ServerContext, stream::BidiStream{RequestType, ResponseType})\n    for message in stream\n        # Process incoming message\n        send!(stream, response)  # Send response\n    end\n    close!(stream)\n    return nothing\nend\n\nReceives BidiStream{TIn, TOut} for bidirectional communication\nIterates over incoming messages with for message in stream\nSends responses with send!(stream, response)\nMust close the stream with close!(stream)\nReturns nothing (responses sent via stream)\nCheck is_cancelled(ctx) to stop early if the client disconnects","title":"Bidirectional Handler Signature"},{"category":"section","location":"examples/04_chat/#Registration","page":"Chat","text":"The generated register_Chat! accepts the handler as Chat = chat_handler; handler signatures are validated at registration time. The generated client stub for this RPC is Chat_Chat_Client.","title":"Registration"},{"category":"section","location":"examples/04_chat/#Testing","page":"Chat","text":"","title":"Testing"},{"category":"section","location":"examples/04_chat/#Run-the-Server","page":"Chat","text":"cd examples/04_chat\njulia --project=../.. server.jl","title":"Run the Server"},{"category":"section","location":"examples/04_chat/#Send-Chat-Messages-with-grpcurl","page":"Chat","text":"echo '{\"user\": \"Alice\", \"text\": \"Hello\"}\n{\"user\": \"Alice\", \"text\": \"How are you?\"}\n{\"user\": \"Alice\", \"text\": \"Goodbye\"}' | grpcurl -plaintext -d @ localhost:50054 chat.Chat/Chat\n\nExpected output:\n\n{\n  \"user\": \"Server\",\n  \"text\": \"You said: Hello\"\n}\n{\n  \"user\": \"Server\",\n  \"text\": \"You said: How are you?\"\n}\n{\n  \"user\": \"Server\",\n  \"text\": \"You said: Goodbye\"\n}","title":"Send Chat Messages with grpcurl"},{"category":"section","location":"examples/04_chat/#All-Four-RPC-Patterns","page":"Chat","text":"You've now seen all gRPC streaming patterns:\n\nPattern Handler Signature Return Registration\nUnary (ctx, request::T) Response register_Greeter_SayHello!(server, handler)\nServer Streaming (ctx, request::T, stream::ServerStream{R}) nothing register_Greeter_SayHelloStream!(server, handler)\nClient Streaming (ctx, stream::ClientStream{T}) Response register_Math_Sum!(server, handler)\nBidirectional (ctx, stream::BidiStream{T, R}) nothing register_Chat_Chat!(server, handler)","title":"All Four RPC Patterns"},{"category":"section","location":"examples/04_chat/#Use-Cases","page":"Chat","text":"Bidirectional streaming is ideal for:\n\nChat applications: Real-time messaging\nCollaborative editing: Multiple users editing simultaneously\nGaming: Real-time game state updates\nVoice/video: Streaming media in both directions\nMonitoring: Bidirectional telemetry and control","title":"Use Cases"},{"category":"section","location":"examples/04_chat/#Next-Steps","page":"Chat","text":"See Calculator for a multi-method service example\nSee Advanced Topics for interceptors, TLS, and compression","title":"Next Steps"},{"category":"section","location":"examples/05_calculator/#Calculator-Multi-Method-Service","page":"Calculator","text":"This example demonstrates a gRPC service with multiple methods and proper error handling.","title":"Calculator - Multi-Method Service"},{"category":"section","location":"examples/05_calculator/#What-You'll-Learn","page":"Calculator","text":"Defining a service with multiple RPC methods\nImplementing multiple handlers\nUsing gRPC status codes for error handling\nWorking with numeric proto types","title":"What You'll Learn"},{"category":"section","location":"examples/05_calculator/#Proto-Definition","page":"Calculator","text":"// calculator.proto\nsyntax = \"proto3\";\npackage calculator;\n\nservice Calculator {\n  rpc Add (CalculatorRequest) returns (CalculatorResponse);\n  rpc Subtract (CalculatorRequest) returns (CalculatorResponse);\n  rpc Multiply (CalculatorRequest) returns (CalculatorResponse);\n  rpc Divide (CalculatorRequest) returns (CalculatorResponse);\n}\n\nmessage CalculatorRequest {\n  double first_number = 1;\n  double second_number = 2;\n}\n\nmessage CalculatorResponse {\n  double result = 1;\n}","title":"Proto Definition"},{"category":"section","location":"examples/05_calculator/#Server-Implementation","page":"Calculator","text":"using gRPCServer\n\n# Include generated types\ninclude(\"generated/calculator/calculator.jl\")\nusing .calculator\n\n# Handlers\nfunction add(ctx::ServerContext, request::CalculatorRequest)::CalculatorResponse\n    @info \"Add\" a=request.first_number b=request.second_number request_id=ctx.request_id\n    CalculatorResponse(request.first_number + request.second_number)\nend\n\nfunction subtract(ctx::ServerContext, request::CalculatorRequest)::CalculatorResponse\n    @info \"Subtract\" a=request.first_number b=request.second_number request_id=ctx.request_id\n    CalculatorResponse(request.first_number - request.second_number)\nend\n\nfunction multiply(ctx::ServerContext, request::CalculatorRequest)::CalculatorResponse\n    @info \"Multiply\" a=request.first_number b=request.second_number request_id=ctx.request_id\n    CalculatorResponse(request.first_number * request.second_number)\nend\n\nfunction divide(ctx::ServerContext, request::CalculatorRequest)::CalculatorResponse\n    @info \"Divide\" a=request.first_number b=request.second_number request_id=ctx.request_id\n    if request.second_number == 0.0\n        throw(GRPCError(StatusCode.INVALID_ARGUMENT, \"Division by zero\"))\n    end\n    CalculatorResponse(request.first_number / request.second_number)\nend\n\n# Register the service with the codegen registration function\nfunction main()\n    server = GRPCServer(\"127.0.0.1\", 50052;\n        enable_health_check = true,\n        enable_reflection = true\n    )\n\n    register_Calculator!(server;\n        Add = add,\n        Subtract = subtract,\n        Multiply = multiply,\n        Divide = divide\n    )\n\n    @info \"Calculator gRPC server starting\" host=\"127.0.0.1\" port=50052\n    run(server)\nend\n\nmain()","title":"Server Implementation"},{"category":"section","location":"examples/05_calculator/#Key-Concepts","page":"Calculator","text":"","title":"Key Concepts"},{"category":"section","location":"examples/05_calculator/#Error-Handling-with-Status-Codes","page":"Calculator","text":"Throw GRPCError to return appropriate status codes:\n\nthrow(GRPCError(StatusCode.INVALID_ARGUMENT, \"Division by zero\"))\n\nCommon status codes:\n\nINVALID_ARGUMENT - Client provided invalid input\nNOT_FOUND - Requested resource doesn't exist\nPERMISSION_DENIED - Client lacks permission\nINTERNAL - Server-side error\nUNAUTHENTICATED - Missing or invalid authentication","title":"Error Handling with Status Codes"},{"category":"section","location":"examples/05_calculator/#Multiple-Methods-in-One-Service","page":"Calculator","text":"Register all four handlers with the generated aggregate function:\n\nregister_Calculator!(server;\n    Add = add,\n    Subtract = subtract,\n    Multiply = multiply,\n    Divide = divide\n)\n\nEach keyword accepts a handler or a (handler, raw_request, raw_response) tuple; handler signatures are validated at registration time.","title":"Multiple Methods in One Service"},{"category":"section","location":"examples/05_calculator/#Numeric-Types","page":"Calculator","text":"Proto double maps to Julia Float64. The generated types handle serialization automatically.","title":"Numeric Types"},{"category":"section","location":"examples/05_calculator/#Testing","page":"Calculator","text":"","title":"Testing"},{"category":"section","location":"examples/05_calculator/#Run-the-Server","page":"Calculator","text":"cd examples/05_calculator\njulia --project=../.. server.jl\n\nNote: This example uses port 50052 (different from hello world examples).","title":"Run the Server"},{"category":"section","location":"examples/05_calculator/#Call-Add-from-Julia","page":"Calculator","text":"In a second terminal, same directory, using the generated client stub (call gRPCClient.grpc_init() once before any call):\n\nusing gRPCServer\ninclude(\"generated/calculator/calculator.jl\")\nusing .calculator\nimport gRPCClient\n\ngRPCClient.grpc_init()\nclient = calculator.Calculator_Add_Client(\"127.0.0.1\", 50052)\nresp = gRPCClient.grpc_sync_request(client, calculator.CalculatorRequest(first_number=5, second_number=3))\n@assert resp.result == 8\nprintln(\"Got: \", resp.result)","title":"Call Add from Julia"},{"category":"section","location":"examples/05_calculator/#Test-Add","page":"Calculator","text":"grpcurl -plaintext -d '{\"first_number\": 10, \"second_number\": 5}' \\\n  localhost:50052 calculator.Calculator/Add\n\nExpected output:\n\n{\n  \"result\": 15\n}","title":"Test Add"},{"category":"section","location":"examples/05_calculator/#Test-Subtract","page":"Calculator","text":"grpcurl -plaintext -d '{\"first_number\": 10, \"second_number\": 3}' \\\n  localhost:50052 calculator.Calculator/Subtract\n\nExpected output:\n\n{\n  \"result\": 7\n}","title":"Test Subtract"},{"category":"section","location":"examples/05_calculator/#Test-Multiply","page":"Calculator","text":"grpcurl -plaintext -d '{\"first_number\": 7, \"second_number\": 6}' \\\n  localhost:50052 calculator.Calculator/Multiply\n\nExpected output:\n\n{\n  \"result\": 42\n}","title":"Test Multiply"},{"category":"section","location":"examples/05_calculator/#Test-Divide","page":"Calculator","text":"grpcurl -plaintext -d '{\"first_number\": 20, \"second_number\": 4}' \\\n  localhost:50052 calculator.Calculator/Divide\n\nExpected output:\n\n{\n  \"result\": 5\n}","title":"Test Divide"},{"category":"section","location":"examples/05_calculator/#Test-Error-Handling-(Division-by-Zero)","page":"Calculator","text":"grpcurl -plaintext -d '{\"first_number\": 10, \"second_number\": 0}' \\\n  localhost:50052 calculator.Calculator/Divide\n\nExpected output:\n\nERROR:\n  Code: InvalidArgument\n  Message: Division by zero","title":"Test Error Handling (Division by Zero)"},{"category":"section","location":"examples/05_calculator/#Best-Practices","page":"Calculator","text":"","title":"Best Practices"},{"category":"section","location":"examples/05_calculator/#Input-Validation","page":"Calculator","text":"Always validate inputs before processing:\n\nfunction handler(ctx::ServerContext, request::RequestType)\n    if !is_valid(request)\n        throw(GRPCError(StatusCode.INVALID_ARGUMENT, \"Invalid input: ...\"))\n    end\n    # Process valid request\nend","title":"Input Validation"},{"category":"section","location":"examples/05_calculator/#Consistent-Error-Messages","page":"Calculator","text":"Provide clear, actionable error messages:\n\n# Good\nthrow(GRPCError(StatusCode.INVALID_ARGUMENT, \"Division by zero\"))\n\n# Better\nthrow(GRPCError(StatusCode.INVALID_ARGUMENT,\n    \"Cannot divide $(request.first_number) by zero\"))","title":"Consistent Error Messages"},{"category":"section","location":"examples/05_calculator/#Logging","page":"Calculator","text":"Log request details for debugging:\n\n@info \"Operation\" a=request.first_number b=request.second_number request_id=ctx.request_id","title":"Logging"},{"category":"section","location":"examples/05_calculator/#Next-Steps","page":"Calculator","text":"For production features, see Advanced Topics covering:\n\nInterceptors for logging, authentication, and rate limiting\nTLS configuration for secure connections\nCompression for large messages\nHealth checking for load balancers","title":"Next Steps"},{"category":"section","location":"performance/#Performance","page":"Performance","text":"","title":"Performance"},{"category":"section","location":"performance/#Zero-copy-framing","page":"Performance","text":"The framing layer reads request bytes directly into a single reusable buffer and hands the decoder a view into it, so a received message is not copied between the socket and ProtoBuf decoding.\n\nA throughput and allocation benchmark lives under benchmark/:\n\njulia --project=benchmark -e 'using Pkg; Pkg.instantiate()'   # first time\njulia --project=benchmark --threads=auto benchmark/run.jl\n\nSee Advanced Topics — Concurrency model for how per-stream tasks and the thread count affect handler parallelism.","title":"Zero-copy framing"},{"category":"section","location":"performance/#HTTP/2-flow-control-window-and-large-uploads","page":"Performance","text":"Large client-to-server messages (big request protobufs and client streaming) are bounded by the HTTP/2 flow-control window. At the protocol-default 64 KiB stream and connection windows, in-flight upload bytes are capped near 64 KiB, so upload throughput is limited to roughly window / round-trip-time. On localhost this is invisible, but over a network with a 10 ms round trip it caps uploads near 6 MB/s regardless of message size. Downloads (server to client) are not affected the same way, since HTTP.jl already batches outgoing DATA frames.\n\nGRPCServer exposes two keywords that raise the receive windows, forwarded to the HTTP/2 backend. All default to the protocol defaults, so behavior is unchanged unless set:\n\nh2_initial_window_size (default 65535): the per-stream receive window the server advertises via SETTINGS_INITIAL_WINDOW_SIZE\nh2_connection_window_size (default 65535): the connection-level receive window, applied with an initial WINDOW_UPDATE when above 65535\n\nThese keywords are honored only by HTTPjlBackend. On PureHTTP2Backend and Nghttp2Backend, explicitly setting a non-default (or even default) value raises UnsupportedFeatureError at construction instead of being silently ignored; omit them to use those backends' defaults.\n\n# Size the window to the bandwidth-delay product, e.g. 8 MiB for a high-BDP link.\nserver = GRPCServer(\"0.0.0.0\", 50051;\n    h2_initial_window_size = 8 * 1024 * 1024,\n    h2_connection_window_size = 8 * 1024 * 1024)\nrun(server)\n\nTo benefit in both directions, the client must advertise a matching receive window, since an endpoint's send throughput is governed by the peer's advertised window.\n\nTransport tuning that is sometimes expected but does not apply here: there is no TCP send/receive buffer size knob in HTTP.jl 2.0 or its Reseau transport (the kernel autotunes), and TCP_NODELAY is already enabled by default, so small messages are not delayed by Nagle.","title":"HTTP/2 flow-control window and large uploads"},{"category":"section","location":"tls/#TLS","page":"TLS","text":"gRPCServer.jl supports TLS-secured gRPC with real server-side ALPN negotiation. The TLS path performs genuine h2 selection during the handshake via OpenSSL's SSL_CTX_set_alpn_select_cb, reads the negotiated protocol back via SSL_get0_alpn_selected, and rejects any client that does not offer h2 before any HTTP/2 bytes are exchanged.\n\nThis page walks you through setting up a TLS gRPC server in about fifteen minutes. The server can serve any codegen-registered service (see Quick Start); TLS is configured on the GRPCServer itself, so registration is unchanged.","title":"TLS"},{"category":"section","location":"tls/#What-you-need","page":"TLS","text":"A server certificate and private key in PEM format. A self-signed cert is fine for local development; use a real CA-issued cert in production.\nA gRPC client that negotiates ALPN — grpcurl, grpc-go, grpc-java, gRPCClient.jl, and browsers through an Envoy sidecar all qualify.\nOptionally, a client CA certificate if you want to enable mutual TLS (mTLS).","title":"What you need"},{"category":"section","location":"tls/#The-TLSConfig-type","page":"TLS","text":"The full docstring is in the API Reference. Fields:\n\nField Type Default Purpose\ncert_chain String (required) Path to the server certificate chain (PEM).\nprivate_key String (required) Path to the server private key (PEM).\nclient_ca Union{String, Nothing} nothing Client CA bundle for mTLS. Required when require_client_cert = true.\nrequire_client_cert Bool false Whether to require and verify a client certificate.\nmin_version Symbol :TLSv1_2 Minimum TLS version (:TLSv1_2 or :TLSv1_3).\nalpn_protocols Vector{String} [\"h2\"] Ordered ALPN preference list. The server selects the first entry in this list that the client also offers. Empty is a construction-time error.\nhandshake_timeout_ns Int64 0 Optional per-handshake timeout in nanoseconds. 0 leaves it unset.\n\nThe alpn_protocols default of [\"h2\"] is what you want for gRPC. The field exists mainly so tests can exercise preference-order behavior and so future deployments can advertise additional protocols alongside h2 if needed.","title":"The TLSConfig type"},{"category":"section","location":"tls/#Step-1-—-Generate-a-self-signed-certificate","page":"TLS","text":"mkdir -p /tmp/grpc-tls\ncd /tmp/grpc-tls\n\nopenssl req -x509 -newkey rsa:2048 -nodes \\\n    -keyout server.key -out server.crt \\\n    -days 30 -subj \"/CN=localhost\" \\\n    -addext \"subjectAltName=DNS:localhost,IP:127.0.0.1\"","title":"Step 1 — Generate a self-signed certificate"},{"category":"section","location":"tls/#Step-2-—-Start-a-TLS-enabled-server","page":"TLS","text":"using gRPCServer\n\ntls = TLSConfig(\n    cert_chain     = \"/tmp/grpc-tls/server.crt\",\n    private_key    = \"/tmp/grpc-tls/server.key\",\n    alpn_protocols = [\"h2\"],\n    min_version    = :TLSv1_2,\n)\n\nserver = GRPCServer(\"127.0.0.1\", 50443;\n    tls = tls,\n    enable_health_check = true,\n)\n\nstart!(server)\n\nYou should see a startup log line with alpn=[\"h2\"]. If the cert or key file is missing or unreadable, start! raises a TLSHandshakeError whose kind is CONFIG_ERROR before the server reaches the RUNNING state.","title":"Step 2 — Start a TLS-enabled server"},{"category":"section","location":"tls/#Step-3-—-Issue-a-successful-RPC","page":"TLS","text":"grpcurl -insecure \\\n    -d '{\"service\": \"\"}' \\\n    localhost:50443 \\\n    grpc.health.v1.Health/Check\n\nThe server log line for the accepted connection shows alpn=h2 as a value read back directly from the live TLS state.","title":"Step 3 — Issue a successful RPC"},{"category":"section","location":"tls/#Step-4-—-Reject-a-client-that-does-not-offer-h2","page":"TLS","text":"openssl s_client -connect localhost:50443 -alpn http/1.1 </dev/null\n\nThe server logs exactly one line of the form:\n\nTLS handshake rejected  kind=ALPN_MISMATCH peer=127.0.0.1:XXXXX\n\nNo HTTP/2 bytes are exchanged, and the accept loop continues serving other clients.","title":"Step 4 — Reject a client that does not offer h2"},{"category":"section","location":"tls/#Step-5-—-Enable-mutual-TLS-(optional)","page":"TLS","text":"tls_mtls = TLSConfig(\n    cert_chain          = \"/tmp/grpc-tls/server.crt\",\n    private_key         = \"/tmp/grpc-tls/server.key\",\n    client_ca           = \"/tmp/grpc-tls/ca.crt\",\n    require_client_cert = true,\n)\n\nWith require_client_cert = true, the server rejects any client that does not present a certificate signed by a CA in the client_ca bundle. The rejection is logged with kind=PEER_CERT_REJECTED.","title":"Step 5 — Enable mutual TLS (optional)"},{"category":"section","location":"tls/#Step-6-—-Reload-certificates-without-restarting","page":"TLS","text":"# ... later, after writing new cert/key files to the same paths ...\nreload_tls!(server)\n\nreload_tls! builds a new underlying TLS configuration, validates it, and swaps it atomically. In-flight handshakes that already latched the previous configuration complete on the old one; new accepts pick up the new config. If the new configuration is invalid, reload_tls! raises and the server keeps using the previous one.\n\nYou can also set up an automatic watcher that reloads when any watched file's mtime changes:\n\nwatcher = gRPCServer.CertificateWatcher(tls, () -> reload_tls!(server))\ngRPCServer.start_watching!(watcher; interval = 60.0)","title":"Step 6 — Reload certificates without restarting"},{"category":"section","location":"tls/#Troubleshooting","page":"TLS","text":"Symptom Likely cause Fix\nArgumentError: alpn_protocols must not be empty You explicitly passed alpn_protocols = String[]. Pass [\"h2\"] or omit the keyword.\nTLSHandshakeError(kind = CONFIG_ERROR, ...) at start! Cert or key path is wrong, file is unreadable, or the key does not match the cert. Check the paths in the error. openssl x509 -in server.crt -text and openssl rsa -in server.key -check validate them independently.\nkind = ALPN_MISMATCH log lines from a client you trust Client advertises only http/1.1, only h2c, or omits ALPN entirely. Enable ALPN on the client and advertise h2.\nkind = PEER_CERT_REJECTED log lines require_client_cert = true but the client presented no cert, or one not signed by client_ca. Verify the client cert chain and the client_ca path.\nkind = HANDSHAKE_IO_ERROR under load Handshake timed out or the connection reset mid-handshake. If persistent, raise handshake_timeout_ns or investigate network middleboxes.","title":"Troubleshooting"},{"category":"section","location":"tls/#Error-classification","page":"TLS","text":"Every TLS-layer failure throws a TLSHandshakeError whose kind field is one of:\n\nCONFIG_ERROR — raised synchronously by start! when the TLS configuration cannot be loaded at all (missing files, malformed cert, bind failure).\nALPN_MISMATCH — the client did not offer any protocol from the server's alpn_protocols list. Raised per-handshake during the accept loop.\nPEER_CERT_REJECTED — mTLS verification failed. Raised per-handshake.\nHANDSHAKE_IO_ERROR — handshake timed out, reset, or failed for any other reason. Raised per-handshake.\n\nThe three per-handshake kinds produce distinct @warn log lines, so operators can tell configuration errors from client errors from load-induced timeouts at a glance.","title":"Error classification"},{"category":"section","location":"examples/#Examples","page":"Overview","text":"This guide walks you through gRPCServer.jl examples in progressive order, from basic concepts to advanced patterns.","title":"Examples"},{"category":"section","location":"examples/#Learning-Path","page":"Overview","text":"Example RPC Pattern Concepts Directory\nHello World Unary Service definition, basic server examples/01_hello_world/\nHello Stream Server Streaming Multiple responses, cancellation examples/02_hello_stream/\nSum Numbers Client Streaming Multiple requests, aggregation examples/03_sum_numbers/\nChat Bidirectional Real-time messaging examples/04_chat/\nCalculator Unary (multi-method) Error handling, multiple methods examples/05_calculator/\nAdvanced Topics All patterns Interceptors, TLS, compression (documentation only)","title":"Learning Path"},{"category":"section","location":"examples/#Getting-Started","page":"Overview","text":"","title":"Getting Started"},{"category":"section","location":"examples/#Prerequisites","page":"Overview","text":"Install gRPCServer.jl:\nusing Pkg\nPkg.add(\"gRPCServer\")\nInstall grpcurl for testing:\n# macOS\nbrew install grpcurl\n\n# Linux (download binary from releases)\n# Windows (download binary from releases)","title":"Prerequisites"},{"category":"section","location":"examples/#Running-Examples","page":"Overview","text":"Each example directory contains:\n\n*.proto - Protocol buffer service definition\nserver.jl - Julia server implementation\ngenerated/ - Auto-generated Julia types, client stubs, and registration functions\nREADME.md - Detailed usage instructions\n\nTo run any example:\n\ncd examples/<example_name>\njulia --project=../.. server.jl","title":"Running Examples"},{"category":"section","location":"examples/#Example-Workflow","page":"Overview","text":"Start simple: Begin with 01_hello_world to understand basic unary RPC\nServer streaming: Move to 02_hello_stream to learn single request → multiple responses\nClient streaming: Try 03_sum_numbers for multiple requests → single response\nBidirectional: Explore 04_chat for simultaneous bidirectional streaming\nMulti-method: See 05_calculator for multiple methods with error handling\nProduction: Read advanced documentation for interceptors, TLS, compression","title":"Example Workflow"},{"category":"section","location":"examples/#Quick-Reference","page":"Overview","text":"Every example registers its handlers with the generated codegen registration functions (one protojl run emits messages, client stubs, and registration functions together).","title":"Quick Reference"},{"category":"section","location":"examples/#Unary-RPC-(01*hello*world)","page":"Overview","text":"Single request, single response:\n\nfunction handler(ctx::ServerContext, request::RequestType)::ResponseType\n    return ResponseType(...)\nend\n\nregister_Greeter_SayHello!(server) do ctx, req\n    ResponseType(...)\nend","title":"Unary RPC (01helloworld)"},{"category":"section","location":"examples/#Server-Streaming-(02*hello*stream)","page":"Overview","text":"Single request, multiple responses:\n\nfunction handler(ctx::ServerContext, request::RequestType, stream::ServerStream{ResponseType})::Nothing\n    for item in items\n        send!(stream, ResponseType(...))\n    end\n    return nothing\nend\n\nregister_Greeter_SayHelloStream!(server, handler)","title":"Server Streaming (02hellostream)"},{"category":"section","location":"examples/#Client-Streaming-(03*sum*numbers)","page":"Overview","text":"Multiple requests, single response:\n\nfunction handler(ctx::ServerContext, stream::ClientStream{RequestType})\n    for request in stream\n        # Process each request\n    end\n    return ResponseType(...)\nend\n\nregister_Math_Sum!(server, handler)","title":"Client Streaming (03sumnumbers)"},{"category":"section","location":"examples/#Bidirectional-Streaming-(04_chat)","page":"Overview","text":"Multiple requests and responses:\n\nfunction handler(ctx::ServerContext, stream::BidiStream{RequestType, ResponseType})\n    for request in stream\n        send!(stream, ResponseType(...))\n    end\n    close!(stream)\n    return nothing\nend\n\nregister_Chat_Chat!(server, handler)","title":"Bidirectional Streaming (04_chat)"},{"category":"section","location":"examples/#Error-Handling-(05_calculator)","page":"Overview","text":"Return appropriate gRPC status codes:\n\nif invalid_input\n    throw(GRPCError(StatusCode.INVALID_ARGUMENT, \"Error message\"))\nend","title":"Error Handling (05_calculator)"},{"category":"section","location":"examples/#Port-Assignments","page":"Overview","text":"Each example uses a different port:\n\nExample Port\n01helloworld 50051\n02hellostream 50051\n03sumnumbers 50053\n04_chat 50054\n05_calculator 50052","title":"Port Assignments"},{"category":"section","location":"examples/#Next-Steps","page":"Overview","text":"After completing the examples, explore:\n\nQuick Start - Comprehensive setup guide\nAPI Reference - Detailed API documentation","title":"Next Steps"},{"category":"section","location":"examples/01_hello_world/#Hello-World-Basic-Unary-RPC","page":"Hello World","text":"This is the simplest gRPCServer.jl example, demonstrating a basic unary RPC (single request, single response).","title":"Hello World - Basic Unary RPC"},{"category":"section","location":"examples/01_hello_world/#What-You'll-Learn","page":"Hello World","text":"Defining a proto service with a single RPC method\nImplementing a unary RPC handler\nRegistering a handler with the generated codegen registration function\nStarting a gRPC server with health check and reflection","title":"What You'll Learn"},{"category":"section","location":"examples/01_hello_world/#Proto-Definition","page":"Hello World","text":"// greeter.proto\nsyntax = \"proto3\";\npackage helloworld;\n\nservice Greeter {\n  rpc SayHello (HelloRequest) returns (HelloReply);\n}\n\nmessage HelloRequest {\n  string name = 1;\n}\n\nmessage HelloReply {\n  string message = 1;\n}\n\nThis defines:\n\nA Greeter service in the helloworld package\nA single SayHello method that takes a name and returns a greeting","title":"Proto Definition"},{"category":"section","location":"examples/01_hello_world/#Generate-Julia-Types","page":"Hello World","text":"Load both gRPCServer and gRPCClient so one protojl run emits the messages, the client stub, and the registration functions together:\n\nusing ProtoBuf\nusing gRPCServer\nimport gRPCClient\n\nprotojl(\"greeter.proto\", \".\", \"generated\";\n    always_use_modules = true,\n    add_kwarg_constructors = true\n)\n\nThis creates the helloworld module in generated/helloworld/ with HelloRequest/HelloReply message types, the Greeter_SayHello_Client client stub, and register_Greeter!/register_Greeter_SayHello! registration functions.","title":"Generate Julia Types"},{"category":"section","location":"examples/01_hello_world/#Server-Implementation","page":"Hello World","text":"using gRPCServer\n\n# Include generated types\ninclude(\"generated/helloworld/helloworld.jl\")\nusing .helloworld\n\n# Run server\nfunction main()\n    server = GRPCServer(\"127.0.0.1\", 50051;\n        enable_health_check = true,\n        enable_reflection = true\n    )\n\n    register_Greeter!(server; SayHello = (ctx, req) -> HelloReply(\"Hello, $(req.name)!\"))\n\n    @info \"gRPC server starting\" host=\"127.0.0.1\" port=50051\n    run(server)\nend\n\nmain()\n\nEquivalent form — the per-RPC do-block registration registers the same RPC:\n\nregister_Greeter_SayHello!(server) do ctx, req\n    HelloReply(\"Hello, $(req.name)!\")\nend","title":"Server Implementation"},{"category":"section","location":"examples/01_hello_world/#Key-Concepts","page":"Hello World","text":"","title":"Key Concepts"},{"category":"section","location":"examples/01_hello_world/#Handler-Function","page":"Hello World","text":"The handler receives:\n\nctx::ServerContext - Request context with metadata, deadlines, and cancellation\nrequest::HelloRequest - The deserialized request message\n\nThe handler returns the response type directly.","title":"Handler Function"},{"category":"section","location":"examples/01_hello_world/#Registration","page":"Hello World","text":"The generated register_Greeter! (aggregate form) and register_Greeter_SayHello! (per-RPC form) build a MethodDescriptor and call register_method! on the server's dispatcher. Handler signatures are validated at registration time — a mismatched shape throws ArgumentError. For the underlying runtime interface (descriptors, register!, register_method!), see the API Reference.","title":"Registration"},{"category":"section","location":"examples/01_hello_world/#Testing","page":"Hello World","text":"","title":"Testing"},{"category":"section","location":"examples/01_hello_world/#Run-the-Server","page":"Hello World","text":"cd examples/01_hello_world\njulia --project=../.. server.jl","title":"Run the Server"},{"category":"section","location":"examples/01_hello_world/#Call-SayHello-from-Julia","page":"Hello World","text":"In a second terminal, same directory, using the generated client stub (call gRPCClient.grpc_init() once before any call):\n\nusing gRPCServer\ninclude(\"generated/helloworld/helloworld.jl\")\nusing .helloworld\nimport gRPCClient\n\ngRPCClient.grpc_init()\nclient = helloworld.Greeter_SayHello_Client(\"127.0.0.1\", 50051)\nresp = gRPCClient.grpc_sync_request(client, helloworld.HelloRequest(\"Julia\"))\n@assert resp.message == \"Hello, Julia!\"\nprintln(\"Got: \", resp.message)","title":"Call SayHello from Julia"},{"category":"section","location":"examples/01_hello_world/#List-Services","page":"Hello World","text":"grpcurl -plaintext localhost:50051 list\n\nExpected output:\n\ngrpc.health.v1.Health\ngrpc.reflection.v1alpha.ServerReflection\nhelloworld.Greeter","title":"List Services"},{"category":"section","location":"examples/01_hello_world/#Call-SayHello","page":"Hello World","text":"grpcurl -plaintext -d '{\"name\": \"Julia\"}' localhost:50051 helloworld.Greeter/SayHello\n\nExpected output:\n\n{\n  \"message\": \"Hello, Julia!\"\n}","title":"Call SayHello"},{"category":"section","location":"examples/01_hello_world/#Next-Steps","page":"Hello World","text":"Proceed to Hello Stream to learn about server streaming RPC.","title":"Next Steps"},{"category":"section","location":"http2-backends/#HTTP/2-Backends","page":"HTTP/2 Backends","text":"gRPCServer.jl uses a pluggable HTTP/2 backend architecture. The HTTP/2 protocol implementation (frames, HPACK, streams, flow control, connection management) is delegated to an external backend package, which is selected at server construction time via the http2_backend keyword argument.\n\nThe default backend is HTTPjlBackend, which serves gRPC over HTTP.jl (≥ 2.1) — cleartext h2c and TLS (ALPN h2), across all four RPC types plus server reflection. The previous backend, PureHTTP2Backend (the pure-Julia PureHTTP2.jl implementation of RFC 7540/7541), remains a fully-supported, opt-in alternative. Observable gRPC behavior is identical across backends. The backend choice is orthogonal to the codegen interface: services registered through the generated register_*! functions run identically on every backend.","title":"HTTP/2 Backends"},{"category":"section","location":"http2-backends/#Selecting-a-Backend","page":"HTTP/2 Backends","text":"using gRPCServer\n\n# Default: uses HTTPjlBackend (HTTP.jl)\nserver = GRPCServer(\"127.0.0.1\", 50051)\n\n# Opt in to the PureHTTP2 backend (optional dependency: load PureHTTP2 first,\n# which also loads the gRPCServerPureHTTP2Ext extension)\nusing PureHTTP2\nserver = GRPCServer(\"127.0.0.1\", 50051; http2_backend=PureHTTP2Backend())","title":"Selecting a Backend"},{"category":"section","location":"http2-backends/#When-to-choose-which","page":"HTTP/2 Backends","text":"You need… Use\nThe default, on the widely-used Julia HTTP stack HTTPjlBackend (default)\nAny streaming RPC type HTTPjlBackend or PureHTTP2Backend\nRequest bodies larger than ~64 KB HTTPjlBackend — see below\nThe nghttp2 C reference implementation Nghttp2Backend — unary and client-streaming only\nA configurable per-connection concurrent-stream limit HTTPjlBackend (max_concurrent_streams, default 100)\nLive TLS certificate reload (reload_tls!) PureHTTP2Backend\nA pure-Julia HTTP/2 stack with no HTTP.jl dependency at runtime PureHTTP2Backend\n\nwarning: PureHTTP2 does not accept large request bodies\nA unary request whose body exceeds the HTTP/2 initial flow-control window (65535 bytes) does not complete on PureHTTP2Backend: the stream is reset and the request never reaches the handler. Requests up to ~64 KB are unaffected, as are responses of any size.This is the one area where the two backends differ in what they can carry rather than in which features they expose, so weigh it against the capabilities listed above. HTTPjlBackend handles request bodies of any size within max_message_size.\n\nnote: HTTP.jl backend limitations\nBecause HTTP.jl owns the listener and TLS context, the HTTP.jl backend does not support live TLS certificate reload (reload_tls!). mTLS over TLS 1.2 is also currently broken upstream in Reseau (it works over TLS 1.3). Select PureHTTP2Backend() if you need certificate reload. Setting these keywords explicitly now raises UnsupportedFeatureError at construction rather than being silently ignored — see Capability validation.","title":"When to choose which"},{"category":"section","location":"http2-backends/#Capability-validation","page":"HTTP/2 Backends","text":"Backends do not support every feature, and configuration keywords that a backend cannot honor used to be silently ignored. gRPCServer now detects explicitly-set keywords and raises UnsupportedFeatureError at GRPCServer construction when the chosen backend cannot honor them. Omitted keywords never raise.\n\nExplicitness is detected exactly: the constructor captures the configuration keywords in a kwargs... splat, so explicitly re-passing a documented default (e.g. backlog=128 on PureHTTP2Backend) also raises — the signal is that you asked for the knob, not that you changed the value.\n\nPer-backend defaults and capabilities are queryable via backend_defaults and backend_capabilities. The backend-specific constructors — GRPCServerHTTPJl, GRPCServerPureHTTP2, GRPCServerNghttp2 — fix the backend and document in their docstrings which keywords raise on that backend.","title":"Capability validation"},{"category":"section","location":"http2-backends/#Per-backend-capability-matrix","page":"HTTP/2 Backends","text":"✅ = supported · ❌ = not supported: the keyword raises UnsupportedFeatureError on that backend (RPC-type rows refuse per request with UNIMPLEMENTED instead — see the note below). Footnote markers qualify partial or nuanced support.\n\nKeyword HTTPjl PureHTTP2 Nghttp2\nTLS cert/key ✅ ✅ ✅\nmTLS (client_ca, require_client_cert) ✅ ✅ ❌\nmin_version, alpn_protocols, handshake_timeout_ns ✅ ✅ ❌\nreload_tls! ❌ ✅ ❌\nmax_receive_message_length ✅ ❌ ❌\nmax_send_message_length, max_concurrent_requests ✅ ✅ ✅\nmax_connections, max_queued_requests, keepalive_interval, keepalive_timeout ❌ ❌ ❌\nmax_concurrent_streams ✅¹ ❌ ❌\nidle_timeout, read_header_timeout, read_timeout, write_timeout ✅ ❌ ❌\nmax_header_bytes, reuseaddr, backlog ✅ ❌ ❌\nh2_initial_window_size, h2_connection_window_size ✅ ❌ ❌\ndrain_timeout (config) ❌² ✅ ❌\nsend-side compression (compression_enabled=true, compression_threshold, supported_codecs) ❌ ❌ ❌\nreceive-side decompression ✅³ ✅³ ❌³\nserver-streaming / bidi RPCs ✅ ✅ ❌\nclient-streaming RPCs ✅ ✅ ✅\nenable_reflection ✅ ✅ ❌⁴\nenable_health_check ✅ ✅ ❌⁵\n\n¹ Enforced per connection on HTTPjl (default 100). ² Pass stop!(; timeout=) on HTTPjl instead; the config keyword raises. ³ Strict on HTTPjl, lenient on PureHTTP2; nghttp2 performs no decompression    (raw bytes, decompression=false). ⁴ ServerReflectionInfo is a bidi stream, which nghttp2 refuses, so the    keyword raises. ⁵ Check works on nghttp2; Watch is refused per request.\n\nRPC-type rows (server-/bidi-streaming on Nghttp2Backend) are method-level refusals (UNIMPLEMENTED), not construction errors, so they do not raise. max_message_size is never gated: it seeds both directions, the send cap is enforced on every backend, and the receive cap is gated via the explicit max_receive_message_length keyword.","title":"Per-backend capability matrix"},{"category":"section","location":"http2-backends/#The-nghttp2-Backend","page":"HTTP/2 Backends","text":"Nghttp2Backend serves gRPC over the nghttp2 C library through Nghttp2Wrapper.jl, which is an optional dependency — a package extension, not a hard requirement. Load it before constructing the backend:\n\nusing gRPCServer, Nghttp2Wrapper\nserver = GRPCServer(\"127.0.0.1\", 50051; http2_backend = Nghttp2Backend())\n\nConstructing it without Nghttp2Wrapper loaded raises an ArgumentError naming what to load, rather than failing later inside the adapter.\n\nnote: Not available on the Julia 1.10 LTS\nNghttp2Wrapper.jl requires Julia 1.12. It calls nghttp2's size_t API, introduced in nghttp2 1.57.0, and nghttp2_jll is a standard library — so the version of libnghttp2 available is whichever one the Julia sysimage ships, and 1.10 ships 1.52.0.On the LTS, Pkg simply will not install Nghttp2Wrapper, so the extension never loads and Nghttp2Backend() raises. The other two backends are unaffected.\n\nwarning: Unary and client-streaming only\nNghttp2Wrapper's server handler is buffered: it receives a complete request and returns a complete response, so a handler cannot emit messages as it produces them.Unary and client-streaming calls are served correctly — all request messages are in hand, and the single response is emitted at the end.Server-streaming and bidirectional calls are refused with UNIMPLEMENTED and an explanatory message. They are not served with wrong timing: a bidirectional request/response exchange, such as server reflection, would deadlock waiting for a reply that is only flushed once the handler returns.Nghttp2Wrapper's ROADMAP Milestone 7 tracks the incremental handler that would lift this.","title":"The nghttp2 Backend"},{"category":"section","location":"http2-backends/#Shutdown-Semantics","page":"HTTP/2 Backends","text":"stop! terminates in bounded time on both backends, but the HTTP.jl backend needs care because Base.close(::HTTP.Server) polls in an unbounded loop until every tracked connection reports idle. A client that opens a stream and never completes it — HEADERS with no body, or a stream reset mid-call — would block that loop forever. stop! therefore never relies on it alone:\n\n# Immediate: drops in-flight connections via HTTP.forceclose.\nstop!(server; force = true)\n\n# Graceful: lets HTTP.jl drain, then forces after the budget expires.\nstop!(server)                    # budget = HTTPJL_DRAIN_TIMEOUT (10s)\nstop!(server; timeout = 2.0)     # explicit budget\n\nA graceful stop that exhausts its budget logs a warning and forces the close, so stop! always returns. Pass force = true when you do not care about draining — in tests, for instance, where it removes the drain wait entirely.\n\nwarning: Do not call `close` on the underlying HTTP.jl server\nclose(server.backend_handle) bypasses this bounding and can hang indefinitely. Always go through stop!.","title":"Shutdown Semantics"},{"category":"section","location":"http2-backends/#The-Backend-Interface","page":"HTTP/2 Backends","text":"There are two contracts. A backend implements whichever suits the library it wraps.","title":"The Backend Interface"},{"category":"section","location":"http2-backends/#The-raised-contract:-AbstractGRPCStream-and-serve_grpc","page":"HTTP/2 Backends","text":"The preferred one, and what HTTPjlBackend uses. The backend owns its listener and serve loop, and adapts each in-flight call to a per-call stream handle:\n\nserve_grpc(backend, server, on_call)   # start serving; call on_call(stream, peer)\n\non_call receives an AbstractGRPCStream, on which the backend implements:\n\nDirection Methods\nRequest grpc_path, request_metadata, read_message!, is_cancelled\nResponse send_response_headers!, send_message!, send_trailers!, reset!\nTeardown drain_request! (optional; defaults to a no-op)\n\nThis contract carries no assumption about the underlying HTTP/2 types, so a backend wrapping a foreign library — a C binding, or another Julia HTTP stack — does not have to imitate PureHTTP2.jl's object model.\n\nread_message! returns one complete gRPC message, or nothing when no complete message will arrive. Returning nothing for a unary or server-streaming call fails it with INTERNAL; it is not a silent empty request.\n\ndrain_request! exists because a backend may treat an unread request body at handler return as an abandoned request. It is called only after RPCs that read exactly one message, where the client has already half-closed — never on client- or bidirectional-streaming calls, where a peer may legitimately hold its send side open.","title":"The raised contract: AbstractGRPCStream and serve_grpc"},{"category":"section","location":"http2-backends/#The-connection-factory-contract:-create_connection-(legacy)","page":"HTTP/2 Backends","text":"The original contract. As of 1.0 it is legacy: no built-in backend uses it (all three — HTTPjl, PureHTTP2, nghttp2 — drive through serve_grpc), and the frame-loop driver that consumed factory connections moved into the PureHTTP2 package extension. It remains documented for custom backends written against the old interface. The factory returns a connection object compatible with PureHTTP2.jl's HTTP2Connection interface — supporting the following operations:\n\nCategory Methods\nLifecycle process_preface, process_frame, is_open\nStream access get_stream, remove_stream, can_send_on_stream\nSending send_headers, send_data, send_trailers, send_rst_stream, send_goaway\nFrame I/O Frame, encode_frame, decode_frame_header\n\nStream objects returned by get_stream must expose field accessors (stream.id, stream.state, stream.headers_complete, etc.) and accessor functions (get_path, get_header, get_content_type, peek_data, can_send, ...). See the PureHTTP2.jl documentation for the full interface.","title":"The connection-factory contract: create_connection (legacy)"},{"category":"section","location":"http2-backends/#Implementing-a-Custom-Backend","page":"HTTP/2 Backends","text":"Define a new subtype of AbstractHTTP2Backend and implement create_connection:\n\nusing gRPCServer, PureHTTP2\n\nstruct MyBackend <: AbstractHTTP2Backend\n    # backend-specific configuration\nend\n\ngRPCServer.create_connection(backend::MyBackend) = begin\n    # Return an HTTP2Connection-compatible object\n    PureHTTP2.HTTP2Connection()\nend\n\nserver = GRPCServer(\"127.0.0.1\", 50051; http2_backend=MyBackend())\n\nThe connection-factory pattern means gRPCServer.jl calls create_connection once per client; the returned object is then used directly through PureHTTP2.jl's API, so no per-request indirection is added. The cost is that the backend must adapt its underlying types to the HTTP2Connection field interface.\n\nFor a backend wrapping a different HTTP/2 library — a C binding such as nghttp2, or another Julia HTTP stack — prefer the raised contract instead:\n\nstruct MyBackend <: AbstractHTTP2Backend end\n\nfunction gRPCServer.serve_grpc(::MyBackend, server, on_call)\n    # Start the library's own listener; for each incoming call, wrap it as an\n    # AbstractGRPCStream and hand it to on_call(stream, peer).\n    # Return whatever handle stop! should close.\nend\n\n# plus the AbstractGRPCStream methods for that stream type\n\nThat is how HTTPjlBackend is built, and it avoids having to imitate PureHTTP2.jl's object model in a library that has its own.","title":"Implementing a Custom Backend"},{"category":"section","location":"http2-backends/#Future-Backends","page":"HTTP/2 Backends","text":"HTTP.jl was the future backend in earlier versions of this page; its HTTP/2 support has since landed and it is now the default.\n\nThe nghttp2 backend has since landed as Nghttp2Backend — see above. It implements the raised AbstractGRPCStream contract through a package extension, and required no change to the dispatch core, which was the point of that contract.\n\nWhat it does not yet cover is streaming, and that gap is upstream: the incremental handler is Nghttp2Wrapper.jl's ROADMAP Milestone 7.","title":"Future Backends"},{"category":"section","location":"http2-backends/#API-Reference","page":"HTTP/2 Backends","text":"See the HTTP/2 Backend Abstraction section of the API Reference for docstrings on AbstractHTTP2Backend, PureHTTP2Backend, and create_connection.","title":"API Reference"},{"category":"section","location":"api/#API-Reference","page":"API Reference","text":"","title":"API Reference"},{"category":"section","location":"api/#Module","page":"API Reference","text":"","title":"Module"},{"category":"section","location":"api/#Server-Types","page":"API Reference","text":"","title":"Server Types"},{"category":"section","location":"api/#Context-Types","page":"API Reference","text":"","title":"Context Types"},{"category":"section","location":"api/#Service-Registration","page":"API Reference","text":"The generated register_<Service>_<Rpc>! functions build a MethodDescriptor for each RPC and call register_method! on the server's dispatcher; use the generated functions for normal services. The types and functions below are the underlying runtime interface the codegen sits on.\n\nRegistration-time validation is performed by internal helpers:","title":"Service Registration"},{"category":"section","location":"api/#Stream-Types","page":"API Reference","text":"","title":"Stream Types"},{"category":"section","location":"api/#Error-Handling","page":"API Reference","text":"","title":"Error Handling"},{"category":"section","location":"api/#Interceptors","page":"API Reference","text":"","title":"Interceptors"},{"category":"section","location":"api/#Health-Checking","page":"API Reference","text":"","title":"Health Checking"},{"category":"section","location":"api/#Reflection-Support","page":"API Reference","text":"","title":"Reflection Support"},{"category":"section","location":"api/#Server-Lifecycle","page":"API Reference","text":"","title":"Server Lifecycle"},{"category":"section","location":"api/#TLS","page":"API Reference","text":"","title":"TLS"},{"category":"section","location":"api/#Context-Operations","page":"API Reference","text":"cancel! is not exported — call it as gRPCServer.cancel!(ctx).","title":"Context Operations"},{"category":"section","location":"api/#Compression","page":"API Reference","text":"","title":"Compression"},{"category":"section","location":"api/#ProtoBuf-Code-Generation","page":"API Reference","text":"Loading gRPCServer registers its ProtoBuf.jl code generation handler; one protojl run (with gRPCClient.jl loaded too) emits message types, client stubs, and per-service registration functions in a single generated file. protojl is re-exported from ProtoBuf.jl by gRPCServer. See Code Generation for the full walkthrough.","title":"ProtoBuf Code Generation"},{"category":"section","location":"api/#HTTP/2-Backend-Abstraction","page":"API Reference","text":"gRPCServer.jl supports pluggable HTTP/2 backends via an abstract type and a connection-factory method. See HTTP/2 Backends for the full guide.","title":"HTTP/2 Backend Abstraction"},{"category":"section","location":"api/#Raised-stream-handler-contract-(HTTP.jl-backend)","page":"API Reference","text":"The HTTP.jl backend requires a higher-level contract than the connection factory: the backend owns the serve loop and presents each gRPC call as an AbstractGRPCStream. This contract is introduced for the HTTP.jl backend; the request-path integration is in progress.","title":"Raised stream-handler contract (HTTP.jl backend)"},{"category":"section","location":"api/#HTTP/2-Stream-State","page":"API Reference","text":"These functions are used for advanced stream state management, particularly for handling edge cases with client disconnection. As of 1.0 they come from PureHTTP2.jl directly — gRPCServer no longer re-exports them (PureHTTP2 became an optional weak dependency). Load PureHTTP2 and qualify: PureHTTP2.can_send(stream), PureHTTP2.StreamError.\n\ncan_send(stream) — check whether a stream is in a state that accepts outbound data\nStreamError — exception type for HTTP/2 stream-level errors","title":"HTTP/2 Stream State"},{"category":"module","location":"api/#gRPCServer","page":"API Reference","text":"gRPCServer\n\nA native Julia implementation of a gRPC server library.\n\ngRPCServer enables Julia developers to expose services over the gRPC protocol with support for all four RPC patterns (unary, server streaming, client streaming, bidirectional), interceptors, health checking, reflection, TLS/mTLS, and compression.\n\nQuick Start\n\nusing gRPCServer\n\n# Create server\nserver = GRPCServer(\"127.0.0.1\", 50051)\n\n# Register your service\nregister!(server, MyService())\n\n# Start server\nrun(server)\n\nSee the documentation for more examples and API reference.\n\n\n\n\n\n","title":"gRPCServer"},{"category":"type","location":"api/#gRPCServer.GRPCServer","page":"API Reference","text":"GRPCServer\n\nThe main gRPC server managing connections, services, and lifecycle.\n\nFields\n\nhost::String: Server bind address\nport::Int: Server port\nconfig::ServerConfig: Server configuration\nstatus::ServerStatus.T: Current lifecycle state\ndispatcher::RequestDispatcher: Request dispatcher\nhealth_status::Dict{String, HealthStatus.T}: Per-service health status\ninflight::Base.Threads.Atomic{Int}: Requests currently admitted into dispatch (load shedding)\nshed_total::Base.Threads.Atomic{Int}: Total requests rejected at the concurrency cap\ncontext::Any: Server-level payload threaded into each request's ServerContext.payload\n\nConfiguration keywords\n\nThe HTTP/2 backend is selected with http2_backend::AbstractHTTP2Backend (default HTTPjlBackend); context::Any carries a server-level payload. The remaining configuration keywords mirror the ServerConfig fields: max_message_size, max_receive_message_length, max_send_message_length, max_concurrent_streams, max_connections, max_concurrent_requests, max_queued_requests, keepalive_interval, keepalive_timeout, idle_timeout, drain_timeout, read_header_timeout, read_timeout, write_timeout, max_header_bytes, reuseaddr, backlog, tls::Union{TLSConfig, Nothing}, enable_health_check, enable_reflection, debug_mode, log_requests, compression_enabled, compression_threshold, supported_codecs, h2_initial_window_size, h2_connection_window_size.\n\nBackends do not support every feature. Explicitly specifying a keyword the chosen backend cannot honor raises UnsupportedFeatureError at construction instead of silently ignoring it (omitted keywords never raise). Per-backend defaults and the supported keyword set are declared by backend_defaults and backend_capabilities; for convenience, see the backend-specific constructors GRPCServerHTTPJl, GRPCServerPureHTTP2, and GRPCServerNghttp2, whose docstrings list each backend's raising keywords.\n\nExample\n\nserver = GRPCServer(\"0.0.0.0\", 50051)\nregister!(server, GreeterService())\nrun(server)\n\n\n\n\n\n","title":"gRPCServer.GRPCServer"},{"category":"type","location":"api/#gRPCServer.ServerConfig","page":"API Reference","text":"ServerConfig\n\nConfiguration container for gRPC server options.\n\nFields\n\nConnection Limits\n\nmax_connections::Union{Int, Nothing}: Maximum concurrent connections (nothing = unlimited)\nmax_concurrent_streams::Int: Maximum streams per connection (default: 100)\nmax_concurrent_requests::Union{Int, Nothing}: Maximum concurrent requests (default: 1024; nothing or 0 = unlimited, matching the legacy csvance semantics). The admission gate sheds a call arriving past the cap immediately with a trailers-only RESOURCE_EXHAUSTED status — no queue, no waiting (see max_queued_requests). Ships enabled because HTTP.jl allows 100 concurrent streams per connection, so with the cap unset N connections yield 100·N concurrent handler tasks; 1024 bounds that by default while staying well above typical concurrency.\nmax_queued_requests::Int: NOT IMPLEMENTED — accepted for API compatibility only. No request queue exists: a call arriving past max_concurrent_requests is shed immediately with a trailers-only RESOURCE_EXHAUSTED status (no queueing, no waiting). The value has no effect, and explicitly setting it at GRPCServer construction raises UnsupportedFeatureError (default: 1000)\n\nMessage Limits\n\nmax_message_size::Int: Maximum message size in bytes (default: 4MB). Seeds both the receive and send caps; override one side with max_receive_message_length / max_send_message_length (each defaults to max_message_size). The receive cap is enforced by the framing layer on incoming request messages (HTTPjl backend); the send cap is enforced when encoding response messages. The ServerConfig.max_message_size field always reports the larger of the two.\n\nTimeouts (in seconds)\n\nkeepalive_interval::Union{Float64, Nothing}: Interval for keepalive pings (nothing = disabled)\nkeepalive_timeout::Float64: Timeout for keepalive response (default: 20.0)\nidle_timeout::Union{Float64, Nothing}: Close idle connections after this time (default: 300; nothing = never). Aligns with the legacy serve! default. A connection that stops sending bytes — including one holding a partial request body — is closed after this window, bounding slow-body memory accrual.\ndrain_timeout::Float64: Maximum time to wait for graceful shutdown (default: 30.0)\nread_header_timeout::Union{Float64, Nothing}: Max seconds to read request headers before the connection is closed (default: 30.0; nothing disables). Passed through to the HTTP.jl listener.\nread_timeout::Union{Float64, Nothing}: Max seconds to read request data (nothing = disabled, the default). Enabling it defends against a peer that trickles or never finishes a request body, but it also terminates legitimately idle long-lived streaming connections, so set it only for unary or short-lived workloads — idle_timeout (on by default) already bounds stalled bodies at coarser granularity. Passed through to the HTTP.jl listener.\nwrite_timeout::Union{Float64, Nothing}: Max seconds to write response data (nothing = disabled, the default). Passed through to the HTTP.jl listener.\n\nDeadline semantics\n\ngrpc-timeout is parsed strictly into ctx.deadline (INVALID_ARGUMENT if malformed). The deadline is enforced at two points, never mid-execution: a fail-fast pre-check before the handler runs (an already-expired deadline fails with trailers-only DEADLINE_EXCEEDED and the handler is not invoked), and a post-return mapping once the handler has finished. A handler that runs past its deadline is not interrupted — it runs to completion and its result is then mapped to DEADLINE_EXCEEDED. Handlers that must bound their own runtime should check remaining_time/is_cancelled cooperatively or install TimeoutInterceptor (also pre-check-only). Watchdog-based cancellation and a server-side default deadline are future work. Unbounded handler runtime is the main amplification vector for resource exhaustion: pair cooperative deadline checks with a max_concurrent_requests cap sized to memory (see the DoS posture note below).\n\nDoS posture\n\nThe server trusts a peer only up to the configured limits. The shipped defaults are conservative for a reason: HTTP.jl allows 100 concurrent streams per connection, so without a cap N connections imply 100·N concurrent handler tasks, and a stalled request body holds memory until the peer finishes it or the connection is reaped. The defaults bound both — max_concurrent_requests = 1024 caps concurrent handler tasks (further requests are shed with RESOURCE_EXHAUSTED), and idle_timeout = 300 closes connections that stop sending bytes. Still size max_concurrent_requests explicitly to the host's memory and the configured max_message_size in production, and treat any handler that can run for a long time as a DoS vector (see Deadline semantics and SECURITY.md).\n\nHTTP.jl listener knobs (legacy serve! pass-throughs)\n\nmax_header_bytes::Int: Maximum request-header size in bytes (default: 1MiB)\nreuseaddr::Bool: Allow reusing the address on restart (default: true)\nbacklog::Int: Connection backlog for the listener (default: 128)\n\nTLS\n\ntls::Union{TLSConfig, Nothing}: TLS configuration (nothing = insecure)\n\nFeature Toggles\n\nenable_health_check::Bool: Enable built-in health checking service (default: false)\nenable_reflection::Bool: Enable gRPC reflection service (default: false)\ndebug_mode::Bool: Include exception details in error responses (default: false)\nlog_requests::Bool: Log all incoming requests (default: false)\n\nCompression\n\ncompression_enabled::Bool: Enable message compression (default: true)\ncompression_threshold::Int: Minimum bytes before compression (default: 1024)\nsupported_codecs::Vector{CompressionCodec.T}: Supported compression codecs\n\nBackend gating\n\nServerConfig itself is backend-agnostic and always constructible. At GRPCServer construction, however, a configuration keyword that is explicitly set but unsupported by the selected HTTP/2 backend raises UnsupportedFeatureError instead of being silently ignored (omitted keywords never raise). This applies to: max_connections, max_queued_requests, keepalive_interval, keepalive_timeout, the HTTP.jl listener timeouts and knobs, the h2-window keywords, drain_timeout (some backends), send-side compression, mTLS / TLS sub-features (on Nghttp2Backend), enable_reflection (on Nghttp2Backend), and max_concurrent_streams (on PureHTTP2Backend and Nghttp2Backend — the HTTPjlBackend supports it). See HTTP/2 Backends for the per-backend matrix.\n\nExample\n\nconfig = ServerConfig(\n    max_message_size = 8 * 1024 * 1024,  # 8MB\n    enable_health_check = true,\n    enable_reflection = true,\n    debug_mode = false\n)\n\n\n\n\n\n","title":"gRPCServer.ServerConfig"},{"category":"type","location":"api/#gRPCServer.TLSConfig","page":"API Reference","text":"TLSConfig\n\nTLS/mTLS configuration for secure connections.\n\nFields\n\ncert_chain::String: Path to server certificate chain (PEM)\nprivate_key::String: Path to server private key (PEM)\nclient_ca::Union{String, Nothing}: Path to client CA certificate for mTLS\nrequire_client_cert::Bool: Whether to require client certificates\nmin_version::Symbol: Minimum TLS version (:TLSv1_2 or :TLSv1_3)\nalpn_protocols::Vector{String}: Ordered ALPN protocol preference list (default [\"h2\"])\nhandshake_timeout_ns::Int64: Optional per-handshake timeout in nanoseconds; 0 leaves it unset\n\nExample\n\ntls = TLSConfig(\n    cert_chain = \"/path/to/server.crt\",\n    private_key = \"/path/to/server.key\",\n    client_ca = \"/path/to/ca.crt\",  # For mTLS\n    require_client_cert = true,\n    min_version = :TLSv1_2,\n    alpn_protocols = [\"h2\"],\n)\n\n\n\n\n\n","title":"gRPCServer.TLSConfig"},{"category":"module","location":"api/#gRPCServer.ServerStatus","page":"API Reference","text":"ServerStatus\n\nRepresents the lifecycle state of a gRPC server.\n\nStates\n\nSTOPPED: Server is not running\nSTARTING: Server is binding to address\nRUNNING: Server is accepting connections\nDRAINING: Server is completing in-flight requests\nSTOPPING: Server is releasing resources\n\n\n\n\n\n","title":"gRPCServer.ServerStatus"},{"category":"type","location":"api/#gRPCServer.ServerContext","page":"API Reference","text":"ServerContext\n\nRequest-scoped context provided to handler functions.\n\nFields\n\nrequest_id::UUID: Unique identifier for this request\nmethod::String: Full method path (e.g., \"/helloworld.Greeter/SayHello\")\nauthority::String: Authority from :authority pseudo-header\nmetadata::Dict{String, Union{String, Vector{UInt8}}}: Request metadata\nresponse_headers::Dict{String, Union{String, Vector{UInt8}}}: Response headers to send\ntrailers::Dict{String, Union{String, Vector{UInt8}}}: Trailing metadata to send\ndeadline::Union{DateTime, Nothing}: Request deadline (nothing = no deadline). The server does not interrupt a handler when the deadline passes — it is enforced only before dispatch (fail-fast) and after the handler returns (see ServerConfig deadline semantics); handlers should check remaining_time/is_cancelled cooperatively to bound their own runtime.\ncancelled::Bool: Whether the request has been cancelled\npeer::PeerInfo: Client connection information\ntrace_context::Union{Vector{UInt8}, Nothing}: Distributed tracing context\npayload::Any: Arbitrary server-side payload (unused by the transport)\n\nExample\n\nfunction say_hello(ctx::ServerContext, request::HelloRequest)::HelloReply\n    @info \"Request\" id=ctx.request_id method=ctx.method\n\n    # Check cancellation\n    if is_cancelled(ctx)\n        throw(GRPCError(StatusCode.CANCELLED, \"Request cancelled\"))\n    end\n\n    # Set response header\n    set_header!(ctx, \"x-request-id\", string(ctx.request_id))\n\n    # Check deadline\n    remaining = remaining_time(ctx)\n    if remaining !== nothing && remaining < 0\n        throw(GRPCError(StatusCode.DEADLINE_EXCEEDED, \"Deadline exceeded\"))\n    end\n\n    HelloReply(message = \"Hello, $(request.name)!\")\nend\n\n\n\n\n\n","title":"gRPCServer.ServerContext"},{"category":"type","location":"api/#gRPCServer.PeerInfo","page":"API Reference","text":"PeerInfo\n\nClient connection information.\n\nFields\n\naddress::Union{IPv4, IPv6}: Client IP address\nport::Int: Client port\ncertificate::Union{Vector{UInt8}, Nothing}: Client certificate for mTLS (DER-encoded)\n\nExample\n\npeer = ctx.peer\n@info \"Client connected from $(peer.address):$(peer.port)\"\n\n\n\n\n\n","title":"gRPCServer.PeerInfo"},{"category":"type","location":"api/#gRPCServer.ServiceDescriptor","page":"API Reference","text":"ServiceDescriptor\n\nDescribes a gRPC service and its methods.\n\nFields\n\nname::String: Fully-qualified service name (e.g., \"helloworld.Greeter\")\nmethods::Dict{String, MethodDescriptor}: Methods keyed by name\nfile_descriptor::Union{Vector{UInt8}, Nothing}: File descriptor for reflection (optional)\n\nExample\n\nservice = ServiceDescriptor(\n    \"helloworld.Greeter\",\n    Dict(\n        \"SayHello\" => MethodDescriptor(\n            \"SayHello\",\n            MethodType.UNARY,\n            \"helloworld.HelloRequest\",\n            \"helloworld.HelloReply\",\n            say_hello\n        )\n    ),\n    nothing\n)\n\n\n\n\n\n","title":"gRPCServer.ServiceDescriptor"},{"category":"type","location":"api/#gRPCServer.MethodDescriptor","page":"API Reference","text":"MethodDescriptor\n\nDescribes a single RPC method.\n\nFields\n\nname::String: Method name (e.g., \"SayHello\")\nmethod_type::MethodType.T: RPC pattern type\ninput_type::String: Fully-qualified request message type name\noutput_type::String: Fully-qualified response message type name\nhandler::Function: Handler function reference\nraw_request::Bool: Treat the request payload as raw protobuf bytes (skip the type registry / ProtoBuf decode; the handler receives a fresh copy of the raw bytes). Default false.\nraw_response::Bool: Treat the handler's AbstractVector{UInt8} return value as raw protobuf bytes and pass them through verbatim (no ProtoBuf encode). Default false.\n\nHandler Signatures by MethodType\n\nUNARY: (ctx::ServerContext, request::T) -> R\nSERVER_STREAMING: (ctx::ServerContext, request::T, stream::ServerStream{R}) -> Nothing\nCLIENT_STREAMING: (ctx::ServerContext, stream::ClientStream{T}) -> R\nBIDI_STREAMING: (ctx::ServerContext, stream::BidiStream{T,R}) -> Nothing\n\nExample\n\nmethod = MethodDescriptor(\n    \"SayHello\",\n    MethodType.UNARY,\n    \"helloworld.HelloRequest\",\n    \"helloworld.HelloReply\",\n    say_hello\n)\n\n\n\n\n\n","title":"gRPCServer.MethodDescriptor"},{"category":"module","location":"api/#gRPCServer.MethodType","page":"API Reference","text":"MethodType\n\nClassifies RPC method patterns.\n\nValues\n\nUNARY: Single request, single response\nSERVER_STREAMING: Single request, multiple responses\nCLIENT_STREAMING: Multiple requests, single response\nBIDI_STREAMING: Multiple requests, multiple responses\n\n\n\n\n\n","title":"gRPCServer.MethodType"},{"category":"function","location":"api/#gRPCServer.register!","page":"API Reference","text":"register!(registry::ServiceRegistry, descriptor::ServiceDescriptor)\n\nRegister a service in the registry. Also auto-registers protobuf types if Julia types were provided in MethodDescriptor.\n\n\n\n\n\nregister!(server::GRPCServer, service)\n\nRegister a service with the server.\n\nThe service must implement service_descriptor(service) to provide its ServiceDescriptor.\n\nArguments\n\nserver::GRPCServer: The server to register with\nservice: A service implementation\n\nThrows\n\nInvalidServerStateError: If server is not in STOPPED state\nServiceAlreadyRegisteredError: If service is already registered\n\nExample\n\nserver = GRPCServer(\"0.0.0.0\", 50051)\nregister!(server, GreeterService())\n\n\n\n\n\n","title":"gRPCServer.register!"},{"category":"function","location":"api/#gRPCServer.register_method!","page":"API Reference","text":"register_method!(registry::ServiceRegistry, service_name::String, method::MethodDescriptor)\n\nRegister a single method under service_name, creating the service entry (and its ServiceDescriptor) on first use. Unlike register! (which throws ServiceAlreadyRegisteredError if the service exists), repeated calls accumulate methods onto the same service — this is the primitive the generated per-RPC registration functions build on. The handler shape is validated at registration time (see _validate_method_handler!) and the method's Julia types are auto-registered in the type registry.\n\n\n\n\n\nregister_method!(dispatcher::RequestDispatcher, service_name::String, method::MethodDescriptor)\n\nRegister a single method with the dispatcher (see register_method!(::ServiceRegistry, ...)).\n\n\n\n\n\n","title":"gRPCServer.register_method!"},{"category":"function","location":"api/#gRPCServer.services","page":"API Reference","text":"services(server::GRPCServer) -> Vector{String}\n\nGet a list of registered service names.\n\nExample\n\nfor service_name in services(server)\n    println(service_name)\nend\n\n\n\n\n\n","title":"gRPCServer.services"},{"category":"function","location":"api/#gRPCServer.service_descriptor","page":"API Reference","text":"service_descriptor(service) -> ServiceDescriptor\n\nGet the service descriptor for a service implementation.\n\nThis function should be overloaded for custom service types.\n\nExample\n\nstruct GreeterService end\n\nfunction gRPCServer.service_descriptor(::GreeterService)\n    ServiceDescriptor(\n        \"helloworld.Greeter\",\n        Dict(\n            \"SayHello\" => MethodDescriptor(\n                \"SayHello\", MethodType.UNARY,\n                \"helloworld.HelloRequest\", \"helloworld.HelloReply\",\n                say_hello\n            )\n        ),\n        nothing\n    )\nend\n\n\n\n\n\n","title":"gRPCServer.service_descriptor"},{"category":"function","location":"api/#gRPCServer._validate_method_handler!","page":"API Reference","text":"_validate_method_handler!(method::MethodDescriptor)\n\nCheck at registration time that method.handler is callable with the signature its MethodType requires (see _expected_handler_tuple), so mismatched handler shapes fail with a clear ArgumentError at register_! rather than a MethodError on the first call. Untyped/vararg handlers pass; wrong arity, wrong argument types, and raw/typed mismatches are rejected. Return types cannot be checked generically and are not validated.\n\n\n\n\n\n","title":"gRPCServer._validate_method_handler!"},{"category":"function","location":"api/#gRPCServer._expected_handler_tuple","page":"API Reference","text":"_expected_handler_tuple(method::MethodDescriptor) -> Union{Tuple, Nothing}\n\nThe call tuple a handler for method must accept, derived from its MethodType and its Julia input/output types. Raw sides substitute Vector{UInt8} (the raw payload). Returns nothing when the descriptor carries no Julia types (string-typed descriptors) and cannot be shape-checked.\n\nMethodType Expected handler tuple\nUNARY Tuple{ServerContext, ReqT}\nSERVER_STREAMING Tuple{ServerContext, ReqT, ServerStream{RespT}}\nCLIENT_STREAMING Tuple{ServerContext, ClientStream{ReqT}}\nBIDI_STREAMING Tuple{ServerContext, BidiStream{ReqT, RespT}}\n\n\n\n\n\n","title":"gRPCServer._expected_handler_tuple"},{"category":"type","location":"api/#gRPCServer.ServerStream","page":"API Reference","text":"ServerStream{T}\n\nOutgoing stream for server streaming and bidirectional RPCs.\n\nType parameter T is the response message type.\n\nMethods\n\nsend!(stream, message): Send a message\nclose!(stream): End the stream\n\nExample\n\nfunction list_features(ctx::ServerContext, request::Rectangle, stream::ServerStream{Feature})\n    for feature in find_features(request)\n        send!(stream, feature)\n    end\nend\n\n\n\n\n\n","title":"gRPCServer.ServerStream"},{"category":"type","location":"api/#gRPCServer.ClientStream","page":"API Reference","text":"ClientStream{T}\n\nIncoming stream for client streaming and bidirectional RPCs.\n\nType parameter T is the request message type.\n\nImplements the Julia iterator interface for use in for loops.\n\nExample\n\nfunction record_route(ctx::ServerContext, stream::ClientStream{Point})::RouteSummary\n    point_count = 0\n    for point in stream\n        point_count += 1\n        # Process each point\n    end\n    return RouteSummary(point_count=point_count)\nend\n\n\n\n\n\n","title":"gRPCServer.ClientStream"},{"category":"type","location":"api/#gRPCServer.BidiStream","page":"API Reference","text":"BidiStream{T, R}\n\nBidirectional stream combining input (T) and output (R) streams.\n\nType parameters:\n\nT: Request message type (incoming)\nR: Response message type (outgoing)\n\nImplements the iterator interface for incoming messages and provides send! for outgoing messages.\n\nExample\n\nfunction route_chat(ctx::ServerContext, stream::BidiStream{RouteNote, RouteNote})\n    for note in stream  # Iterate incoming messages\n        # Echo back each note\n        send!(stream, note)\n    end\nend\n\n\n\n\n\n","title":"gRPCServer.BidiStream"},{"category":"function","location":"api/#gRPCServer.send!","page":"API Reference","text":"send!(stream::ServerStream{T}, message::T) where T\nsend!(stream::ServerStream{T}, message::T; compress::Bool=true) where T\n\nSend a message on the server stream.\n\nArguments\n\nstream::ServerStream{T}: The stream to send on\nmessage::T: The message to send\ncompress::Bool=true: Whether to compress the message (if compression is negotiated)\n\nThrows\n\nStreamCancelledError: If the stream has been cancelled\nArgumentError: If the stream is closed\n\nExample\n\nsend!(stream, Feature(name=\"Feature 1\", location=Point(latitude=1, longitude=2)))\n\n\n\n\n\nsend!(stream::BidiStream{T, R}, message::R) where {T, R}\nsend!(stream::BidiStream{T, R}, message::R; compress::Bool=true) where {T, R}\n\nSend a message on the bidirectional stream.\n\nExample\n\nsend!(stream, RouteNote(message=\"Hello\", location=point))\n\n\n\n\n\n","title":"gRPCServer.send!"},{"category":"function","location":"api/#gRPCServer.close!","page":"API Reference","text":"close!(stream::BidiStream)\n\nClose the output side of the bidirectional stream.\n\n\n\n\n\n","title":"gRPCServer.close!"},{"category":"module","location":"api/#gRPCServer.StatusCode","page":"API Reference","text":"StatusCode\n\nStandard gRPC status codes per specification.\n\nStatus Codes\n\nOK (0): Not an error; returned on success\nCANCELLED (1): Operation was cancelled\nUNKNOWN (2): Unknown error\nINVALID_ARGUMENT (3): Invalid argument provided\nDEADLINE_EXCEEDED (4): Deadline expired before completion\nNOT_FOUND (5): Requested entity not found\nALREADY_EXISTS (6): Entity already exists\nPERMISSION_DENIED (7): Permission denied\nRESOURCE_EXHAUSTED (8): Resource exhausted\nFAILED_PRECONDITION (9): Precondition check failed\nABORTED (10): Operation aborted\nOUT_OF_RANGE (11): Value out of range\nUNIMPLEMENTED (12): Operation not implemented\nINTERNAL (13): Internal error\nUNAVAILABLE (14): Service unavailable\nDATA_LOSS (15): Data loss or corruption\nUNAUTHENTICATED (16): Request not authenticated\n\n\n\n\n\n","title":"gRPCServer.StatusCode"},{"category":"type","location":"api/#gRPCServer.GRPCError","page":"API Reference","text":"GRPCError <: Exception\n\nException type for gRPC errors with status code, message, and optional details.\n\nFields\n\ncode::StatusCode.T: The gRPC status code\nmessage::String: Human-readable error message\ndetails::Vector{Any}: Additional error details (rich error model)\n\nExample\n\nthrow(GRPCError(StatusCode.NOT_FOUND, \"User not found\", []))\nthrow(GRPCError(StatusCode.INVALID_ARGUMENT, \"Name cannot be empty\"))\n\n\n\n\n\n","title":"gRPCServer.GRPCError"},{"category":"type","location":"api/#gRPCServer.BindError","page":"API Reference","text":"BindError <: Exception\n\nException thrown when the server fails to bind to the configured address.\n\nFields\n\nmessage::String: Description of the bind failure\ncause::Union{Exception, Nothing}: Underlying exception if available\n\n\n\n\n\n","title":"gRPCServer.BindError"},{"category":"type","location":"api/#gRPCServer.ServiceAlreadyRegisteredError","page":"API Reference","text":"ServiceAlreadyRegisteredError <: Exception\n\nException thrown when attempting to register a service with a name that already exists.\n\nFields\n\nservice_name::String: The duplicate service name\n\n\n\n\n\n","title":"gRPCServer.ServiceAlreadyRegisteredError"},{"category":"type","location":"api/#gRPCServer.InvalidServerStateError","page":"API Reference","text":"InvalidServerStateError <: Exception\n\nException thrown when an operation is attempted in an invalid server state.\n\nFields\n\nexpected::ServerStatus.T: The expected server state\nactual::ServerStatus.T: The actual server state\n\n\n\n\n\n","title":"gRPCServer.InvalidServerStateError"},{"category":"type","location":"api/#gRPCServer.MethodSignatureError","page":"API Reference","text":"MethodSignatureError <: Exception\n\nException thrown when a handler method has an invalid signature.\n\nFields\n\nmethod_name::String: The method with invalid signature\nexpected::String: Description of expected signature\nactual::String: Description of actual signature\n\n\n\n\n\n","title":"gRPCServer.MethodSignatureError"},{"category":"type","location":"api/#gRPCServer.StreamCancelledError","page":"API Reference","text":"StreamCancelledError <: Exception\n\nException thrown when a stream operation is attempted on a cancelled stream.\n\nFields\n\nreason::String: The reason for cancellation\n\n\n\n\n\n","title":"gRPCServer.StreamCancelledError"},{"category":"type","location":"api/#gRPCServer.UnsupportedFeatureError","page":"API Reference","text":"UnsupportedFeatureError <: Exception\n\nException thrown when a feature is explicitly requested that the selected HTTP/2 backend does not support.\n\nFields\n\nfeature::Symbol: The feature (configuration keyword) that is unsupported\nbackend::Type: The backend type that does not support the feature\nmessage::String: Human-readable explanation, including the way out\n\n\n\n\n\n","title":"gRPCServer.UnsupportedFeatureError"},{"category":"function","location":"api/#gRPCServer.status_code_to_http","page":"API Reference","text":"status_code_to_http(code::StatusCode.T) -> Int\n\nMap a gRPC status code to the appropriate HTTP status code.\n\n\n\n\n\n","title":"gRPCServer.status_code_to_http"},{"category":"function","location":"api/#gRPCServer.exception_to_status_code","page":"API Reference","text":"exception_to_status_code(e::Exception) -> StatusCode.T\n\nMap a Julia exception to a gRPC status code.\n\n\n\n\n\n","title":"gRPCServer.exception_to_status_code"},{"category":"function","location":"api/#gRPCServer.http2_to_grpc_status","page":"API Reference","text":"http2_to_grpc_status(http2_error_code::UInt32) -> StatusCode.T\n\nMap an HTTP/2 error code to a gRPC status code.\n\nThis mapping is per the gRPC HTTP/2 protocol specification: https://github.com/grpc/grpc/blob/master/doc/PROTOCOL-HTTP2.md\n\nHTTP/2 Error Code Mappings\n\nNOERROR (0x0) → INTERNAL (unexpected for RSTSTREAM)\nPROTOCOL_ERROR (0x1) → INTERNAL\nINTERNAL_ERROR (0x2) → INTERNAL\nFLOWCONTROLERROR (0x3) → INTERNAL\nSETTINGS_TIMEOUT (0x4) → INTERNAL\nSTREAM_CLOSED (0x5) → INTERNAL\nFRAMESIZEERROR (0x6) → INTERNAL\nREFUSED_STREAM (0x7) → UNAVAILABLE\nCANCEL (0x8) → CANCELLED\nCOMPRESSION_ERROR (0x9) → INTERNAL\nCONNECT_ERROR (0xa) → INTERNAL\nENHANCEYOURCALM (0xb) → RESOURCE_EXHAUSTED\nINADEQUATESECURITY (0xc) → PERMISSIONDENIED\nHTTP11_REQUIRED (0xd) → INTERNAL\n\nExample\n\ngrpc_status = http2_to_grpc_status(0x08)  # CANCEL → CANCELLED\n\n\n\n\n\nhttp2_to_grpc_status(http2_error_code::Integer) -> StatusCode.T\n\nConvenience method accepting any integer type.\n\n\n\n\n\n","title":"gRPCServer.http2_to_grpc_status"},{"category":"type","location":"api/#gRPCServer.Interceptor","page":"API Reference","text":"Interceptor\n\nAbstract type for gRPC interceptors.\n\nInterceptors are callables that wrap handler execution, allowing for cross-cutting concerns like logging, authentication, metrics, and error handling.\n\nRequired Interface\n\nSubtypes must be callable with signature:\n\n(interceptor)(ctx::ServerContext, request_or_stream, info::MethodInfo, next::Function) -> response\n\nArguments\n\nctx::ServerContext: Request context\nrequest_or_stream: Request message (unary/server streaming) or stream (client/bidi streaming)\ninfo::MethodInfo: Method information\nnext::Function: Next handler in the chain (call to continue processing)\n\nExample\n\nstruct AuthInterceptor <: Interceptor\n    required_scope::String\nend\n\nfunction (i::AuthInterceptor)(ctx, request, info, next)\n    token = get_metadata_string(ctx, \"authorization\")\n    if token === nothing\n        throw(GRPCError(StatusCode.UNAUTHENTICATED, \"Missing authorization\"))\n    end\n\n    # Validate token and check scope\n    if !validate_token(token, i.required_scope)\n        throw(GRPCError(StatusCode.PERMISSION_DENIED, \"Insufficient scope\"))\n    end\n\n    return next(ctx, request)\nend\n\n\n\n\n\n","title":"gRPCServer.Interceptor"},{"category":"type","location":"api/#gRPCServer.MethodInfo","page":"API Reference","text":"MethodInfo\n\nInformation about the method being called, provided to interceptors.\n\nFields\n\nservice_name::String: Fully-qualified service name (e.g., \"helloworld.Greeter\")\nmethod_name::String: Method name (e.g., \"SayHello\")\nmethod_type::MethodType.T: RPC pattern type\n\nExample\n\nstruct LoggingInterceptor <: Interceptor end\n\nfunction (::LoggingInterceptor)(ctx, request, info::MethodInfo, next)\n    @info \"Calling\" service=info.service_name method=info.method_name\n    return next(ctx, request)\nend\n\n\n\n\n\n","title":"gRPCServer.MethodInfo"},{"category":"type","location":"api/#gRPCServer.LoggingInterceptor","page":"API Reference","text":"LoggingInterceptor <: Interceptor\n\nBuilt-in interceptor that logs request/response information.\n\nFields\n\nlog_requests::Bool: Log incoming requests (default: true)\nlog_responses::Bool: Log responses (default: true)\nlog_errors::Bool: Log errors (default: true)\n\nExample\n\nadd_interceptor!(server, LoggingInterceptor())\n\n\n\n\n\n","title":"gRPCServer.LoggingInterceptor"},{"category":"type","location":"api/#gRPCServer.MetricsInterceptor","page":"API Reference","text":"MetricsInterceptor <: Interceptor\n\nBuilt-in interceptor that collects request metrics.\n\nFields\n\non_request::Function: Called with (method, request_size) on each request\non_response::Function: Called with (method, status, durationms, responsesize) on each response\n\nExample\n\nmetrics = MetricsInterceptor(\n    on_request = (method, size) -> increment_counter(\"grpc_requests\", method),\n    on_response = (method, status, ms, size) -> record_histogram(\"grpc_duration\", ms, method, status)\n)\nadd_interceptor!(server, metrics)\n\n\n\n\n\n","title":"gRPCServer.MetricsInterceptor"},{"category":"type","location":"api/#gRPCServer.TimeoutInterceptor","page":"API Reference","text":"TimeoutInterceptor <: Interceptor\n\nBuilt-in interceptor that enforces request deadlines.\n\nFields\n\ndefault_timeout_ms::Union{Int, Nothing}: Default timeout in milliseconds if none specified\n\nExample\n\nadd_interceptor!(server, TimeoutInterceptor(default_timeout_ms=30000))  # 30 second default\n\n\n\n\n\n","title":"gRPCServer.TimeoutInterceptor"},{"category":"type","location":"api/#gRPCServer.RecoveryInterceptor","page":"API Reference","text":"RecoveryInterceptor <: Interceptor\n\nBuilt-in interceptor that catches panics and converts them to gRPC errors.\n\nFields\n\ninclude_stack_trace::Bool: Include stack trace in error message (debug mode only)\n\nExample\n\nadd_interceptor!(server, RecoveryInterceptor(include_stack_trace=true))\n\n\n\n\n\n","title":"gRPCServer.RecoveryInterceptor"},{"category":"function","location":"api/#gRPCServer.add_interceptor!","page":"API Reference","text":"add_interceptor!(dispatcher::RequestDispatcher, interceptor::Interceptor)\n\nAdd a global interceptor.\n\n\n\n\n\nadd_interceptor!(dispatcher::RequestDispatcher, service_name::String, interceptor::Interceptor)\n\nAdd a service-specific interceptor.\n\n\n\n\n\nadd_interceptor!(server::GRPCServer, interceptor::Interceptor)\n\nAdd a global interceptor that applies to all services.\n\nExample\n\nadd_interceptor!(server, LoggingInterceptor())\nadd_interceptor!(server, MetricsInterceptor())\n\n\n\n\n\nadd_interceptor!(server::GRPCServer, service_name::String, interceptor::Interceptor)\n\nAdd an interceptor for a specific service.\n\nExample\n\nadd_interceptor!(server, \"helloworld.Greeter\", AuthInterceptor())\n\n\n\n\n\n","title":"gRPCServer.add_interceptor!"},{"category":"module","location":"api/#gRPCServer.HealthStatus","page":"API Reference","text":"HealthStatus\n\nService health state for the health checking service.\n\nValues\n\nUNKNOWN: Health status is unknown\nSERVING: Service is healthy and accepting requests\nNOT_SERVING: Service is not healthy\nSERVICE_UNKNOWN: Service is not registered\n\n\n\n\n\n","title":"gRPCServer.HealthStatus"},{"category":"function","location":"api/#gRPCServer.set_health!","page":"API Reference","text":"set_health!(server::GRPCServer, status::HealthStatus.T)\n\nSet the health status for the overall server.\n\nExample\n\nset_health!(server, HealthStatus.NOT_SERVING)  # Server entering maintenance\n\n\n\n\n\nset_health!(server::GRPCServer, service_name::String, status::HealthStatus.T)\n\nSet the health status for a specific service.\n\nExample\n\nset_health!(server, \"helloworld.Greeter\", HealthStatus.NOT_SERVING)\n\n\n\n\n\n","title":"gRPCServer.set_health!"},{"category":"function","location":"api/#gRPCServer.get_health","page":"API Reference","text":"get_health(server::GRPCServer, service_name::String=\"\") -> HealthStatus.T\n\nGet the health status for a service (or overall server if empty string).\n\n\n\n\n\n","title":"gRPCServer.get_health"},{"category":"constant","location":"api/#gRPCServer.HEALTH_DESCRIPTOR","page":"API Reference","text":"HEALTH_DESCRIPTOR::Vector{Vector{UInt8}}\n\nExtracted FileDescriptorProto messages for the gRPC Health service (grpc.health.v1). Each element is a serialized FileDescriptorProto that can be returned by the reflection service.\n\nGenerated from: specs/001-grpc-server/contracts/health.proto\n\n\n\n\n\n","title":"gRPCServer.HEALTH_DESCRIPTOR"},{"category":"constant","location":"api/#gRPCServer.REFLECTION_DESCRIPTOR","page":"API Reference","text":"REFLECTION_DESCRIPTOR::Vector{Vector{UInt8}}\n\nExtracted FileDescriptorProto messages for the gRPC Server Reflection service (grpc.reflection.v1alpha). Each element is a serialized FileDescriptorProto that can be returned by the reflection service.\n\nGenerated from: specs/001-grpc-server/contracts/reflection.proto\n\n\n\n\n\n","title":"gRPCServer.REFLECTION_DESCRIPTOR"},{"category":"function","location":"api/#gRPCServer.has_health_descriptor","page":"API Reference","text":"has_health_descriptor() -> Bool\n\nCheck if the Health service descriptor is available.\n\n\n\n\n\n","title":"gRPCServer.has_health_descriptor"},{"category":"function","location":"api/#gRPCServer.has_reflection_descriptor","page":"API Reference","text":"has_reflection_descriptor() -> Bool\n\nCheck if the Reflection service descriptor is available.\n\n\n\n\n\n","title":"gRPCServer.has_reflection_descriptor"},{"category":"function","location":"api/#gRPCServer.start!","page":"API Reference","text":"start!(server::GRPCServer)\n\nStart the server and begin accepting connections.\n\nThis is a non-blocking call. Use run(server) for blocking operation.\n\nThrows\n\nInvalidServerStateError: If server is not in STOPPED state\nBindError: If the server cannot bind to the address\n\nExample\n\nstart!(server)\n# Server is now running in background\n\n\n\n\n\n","title":"gRPCServer.start!"},{"category":"function","location":"api/#gRPCServer.stop!","page":"API Reference","text":"stop!(server::GRPCServer; force::Bool=false, timeout::Float64=0.0)\n\nStop the server.\n\nArguments\n\nserver::GRPCServer: The server to stop\nforce::Bool=false: If true, immediately close all connections\ntimeout::Float64=0.0: Override drain timeout (0 = use config)\n\nThrows\n\nInvalidServerStateError: If server is not running\n\nExample\n\nstop!(server)  # Graceful shutdown\nstop!(server; force=true)  # Immediate shutdown\n\n\n\n\n\n","title":"gRPCServer.stop!"},{"category":"function","location":"api/#gRPCServer.reload_tls!","page":"API Reference","text":"reload_tls!(server::GRPCServer)\n\nReload TLS certificates from disk.\n\nThis allows certificate rotation without server restart.\n\nThrows\n\nInvalidServerStateError: If server is not running\nArgumentError: If TLS is not configured\n\nExample\n\nreload_tls!(server)  # Reload certificates\n\n\n\n\n\n","title":"gRPCServer.reload_tls!"},{"category":"function","location":"api/#gRPCServer.set_header!","page":"API Reference","text":"set_header!(ctx::ServerContext, key::String, value::String)\nset_header!(ctx::ServerContext, key::String, value::Vector{UInt8})\n\nSet a response header to be sent before the response body.\n\nHeaders must be set before the first response message is sent. Binary headers should have a \"-bin\" suffix in the key name.\n\nExample\n\nset_header!(ctx, \"x-custom-header\", \"custom-value\")\nset_header!(ctx, \"x-binary-data-bin\", UInt8[0x01, 0x02, 0x03])\n\n\n\n\n\n","title":"gRPCServer.set_header!"},{"category":"function","location":"api/#gRPCServer.set_trailer!","page":"API Reference","text":"set_trailer!(ctx::ServerContext, key::String, value::String)\nset_trailer!(ctx::ServerContext, key::String, value::Vector{UInt8})\n\nSet trailing metadata to be sent after the response body.\n\nTrailers are sent at the end of the response stream and can be used to communicate status information determined during processing.\n\nExample\n\nset_trailer!(ctx, \"x-processing-time\", \"150ms\")\n\n\n\n\n\n","title":"gRPCServer.set_trailer!"},{"category":"function","location":"api/#gRPCServer.get_metadata","page":"API Reference","text":"get_metadata(ctx::ServerContext, key::String) -> Union{String, Vector{UInt8}, Nothing}\n\nGet request metadata by key (case-insensitive).\n\nExample\n\nauth = get_metadata(ctx, \"authorization\")\nif auth === nothing\n    throw(GRPCError(StatusCode.UNAUTHENTICATED, \"Missing authorization\"))\nend\n\n\n\n\n\n","title":"gRPCServer.get_metadata"},{"category":"function","location":"api/#gRPCServer.get_metadata_string","page":"API Reference","text":"get_metadata_string(ctx::ServerContext, key::String) -> Union{String, Nothing}\n\nGet request metadata as a string (returns nothing for binary metadata).\n\n\n\n\n\n","title":"gRPCServer.get_metadata_string"},{"category":"function","location":"api/#gRPCServer.get_metadata_binary","page":"API Reference","text":"get_metadata_binary(ctx::ServerContext, key::String) -> Union{Vector{UInt8}, Nothing}\n\nGet request metadata as binary (converts strings to bytes if needed).\n\n\n\n\n\n","title":"gRPCServer.get_metadata_binary"},{"category":"function","location":"api/#gRPCServer.remaining_time","page":"API Reference","text":"remaining_time(ctx::ServerContext) -> Union{Float64, Nothing}\n\nGet the remaining time until the deadline in seconds.\n\nReturns nothing if no deadline is set. Returns negative value if deadline has passed.\n\nExample\n\nremaining = remaining_time(ctx)\nif remaining !== nothing && remaining < 0\n    throw(GRPCError(StatusCode.DEADLINE_EXCEEDED, \"Deadline exceeded\"))\nend\n\n\n\n\n\n","title":"gRPCServer.remaining_time"},{"category":"function","location":"api/#gRPCServer.is_cancelled","page":"API Reference","text":"is_cancelled(ctx::ServerContext) -> Bool\n\nCheck if the request has been cancelled by the client.\n\nExample\n\nif is_cancelled(ctx)\n    throw(GRPCError(StatusCode.CANCELLED, \"Request cancelled by client\"))\nend\n\n\n\n\n\nis_cancelled(stream::ClientStream) -> Bool\n\nCheck if the stream has been cancelled.\n\n\n\n\n\nis_cancelled(stream::BidiStream) -> Bool\n\nCheck if the stream has been cancelled.\n\n\n\n\n\n","title":"gRPCServer.is_cancelled"},{"category":"function","location":"api/#gRPCServer.cancel!","page":"API Reference","text":"cancel!(ctx::ServerContext)\n\nMark the request as cancelled.\n\n\n\n\n\n","title":"gRPCServer.cancel!"},{"category":"module","location":"api/#gRPCServer.CompressionCodec","page":"API Reference","text":"CompressionCodec\n\nSupported compression algorithms for gRPC messages.\n\nValues\n\nIDENTITY: No compression\nGZIP: Gzip compression\nDEFLATE: Deflate compression\n\n\n\n\n\n","title":"gRPCServer.CompressionCodec"},{"category":"function","location":"api/#gRPCServer.compress","page":"API Reference","text":"compress(data::Vector{UInt8}, codec::CompressionCodec.T) -> Vector{UInt8}\n\nCompress data using the specified codec.\n\n\n\n\n\n","title":"gRPCServer.compress"},{"category":"function","location":"api/#gRPCServer.decompress","page":"API Reference","text":"decompress(data::Vector{UInt8}, codec::CompressionCodec.T) -> Vector{UInt8}\n\nDecompress data using the specified codec.\n\n\n\n\n\n","title":"gRPCServer.decompress"},{"category":"function","location":"api/#gRPCServer.codec_name","page":"API Reference","text":"codec_name(codec::CompressionCodec.T) -> String\n\nGet the gRPC encoding name for a compression codec.\n\n\n\n\n\n","title":"gRPCServer.codec_name"},{"category":"function","location":"api/#gRPCServer.parse_codec","page":"API Reference","text":"parse_codec(name::AbstractString) -> Union{CompressionCodec.T, Nothing}\n\nParse a gRPC encoding name to a compression codec. Returns nothing if the encoding is not supported.\n\n\n\n\n\n","title":"gRPCServer.parse_codec"},{"category":"function","location":"api/#gRPCServer.negotiate_compression","page":"API Reference","text":"negotiate_compression(\n    client_encodings::Vector{CompressionCodec.T},\n    server_codecs::Vector{CompressionCodec.T}\n) -> CompressionCodec.T\n\nNegotiate compression codec between client and server. Returns the first codec supported by both, preferring client order. Falls back to IDENTITY if no common codec.\n\n\n\n\n\n","title":"gRPCServer.negotiate_compression"},{"category":"function","location":"api/#gRPCServer.grpc_register_service_codegen","page":"API Reference","text":"grpc_register_service_codegen()\n\nRegister gRPCServer's external code generation handler with ProtoBuf.jl so that a subsequent protojl run emits server descriptors (<Service>_<Rpc>_Method builders, register_<Service>_<Rpc>! registration functions, and a register_<Service>! aggregate) for each service in the .proto.\n\nThis is called automatically from the module's __init__, so it normally does not need to be invoked directly. It can be called explicitly (e.g. gRPCServer.grpc_register_service_codegen()) to re-register the handler after ProtoBuf.jl has been reloaded.\n\n\n\n\n\n","title":"gRPCServer.grpc_register_service_codegen"},{"category":"type","location":"api/#gRPCServer.AbstractHTTP2Backend","page":"API Reference","text":"AbstractHTTP2Backend\n\nAbstract type representing an HTTP/2 backend for gRPCServer.jl.\n\nBackends drive the server through one of two contracts:\n\nserve_grpc (primary): the backend owns its listener/serve loop and presents each incoming call as an AbstractGRPCStream to dispatch_grpc_call. See serve_grpc, uses_serve_grpc, and stop_serving!. All three built-in backends use this contract.\ncreate_connection (legacy): the backend implements create_connection to return an HTTP/2 connection object driven by gRPCServer's own frame loop. Kept for custom backends written against the old interface; the connection object must be compatible with PureHTTP2.jl's HTTP2Connection interface (connection lifecycle: process_preface, process_frame, is_open; stream management: get_stream, remove_stream, can_send_on_stream; sending: send_headers, send_data, send_trailers, send_rst_stream, send_goaway; frame I/O: Frame, encode_frame, decode_frame_header).\n\nSee the HTTP/2 Backends documentation page for details on implementing a custom backend.\n\n\n\n\n\n","title":"gRPCServer.AbstractHTTP2Backend"},{"category":"type","location":"api/#gRPCServer.PureHTTP2Backend","page":"API Reference","text":"PureHTTP2Backend <: AbstractHTTP2Backend\n\nOpt-in pure-Julia HTTP/2 backend using PureHTTP2.jl (the default backend is HTTPjlBackend; pass http2_backend=PureHTTP2Backend() to the GRPCServer constructor to select it).\n\nPureHTTP2 is an optional dependency. Load it before constructing the backend:\n\nusing gRPCServer, PureHTTP2\nserver = GRPCServer(\"127.0.0.1\", 50051; http2_backend = PureHTTP2Backend())\n\nThis backend delegates all HTTP/2 operations to the PureHTTP2 package, which provides a pure-Julia implementation of the HTTP/2 protocol (RFC 7540) including HPACK header compression (RFC 7541), stream management, and flow control.\n\n\n\n\n\n","title":"gRPCServer.PureHTTP2Backend"},{"category":"function","location":"api/#gRPCServer.create_connection","page":"API Reference","text":"create_connection(backend::AbstractHTTP2Backend)\n\nCreate a new HTTP/2 connection using the specified backend.\n\nReturns an HTTP/2 connection object that will be used to manage a single client connection. The returned object must support the full HTTP/2 connection interface (see AbstractHTTP2Backend for requirements).\n\nThis is the legacy custom-backend contract. New backends should implement serve_grpc instead; the built-in backends all do. PureHTTP2Backend implements create_connection inside the PureHTTP2 extension.\n\nExamples\n\nbackend = PureHTTP2Backend()\nconn = create_connection(backend)  # Returns a PureHTTP2.HTTP2Connection\n\n\n\n\n\n","title":"gRPCServer.create_connection"},{"category":"type","location":"api/#gRPCServer.HTTPjlBackend","page":"API Reference","text":"HTTPjlBackend <: AbstractHTTP2Backend\n\nHTTP/2 backend backed by HTTP.jl (>= 2.0.0).\n\nHTTP.jl owns the TCP listener and the TLS/ALPN handshake; this backend delegates the HTTP/2 protocol (frames, HPACK, flow control, trailers) to HTTP.jl and adapts each HTTP.Stream to the AbstractGRPCStream contract.\n\nConstructing an HTTPjlBackend validates that the loaded HTTP.jl can serve HTTP/2 and raises a clear error otherwise.\n\nKnown limitations (current HTTP.jl)\n\nNo live TLS certificate reload (reload_tls!); HTTP.jl owns the TLS context.\n\nSelect PureHTTP2Backend() if you need certificate reload.\n\n\n\n\n\n","title":"gRPCServer.HTTPjlBackend"},{"category":"type","location":"api/#gRPCServer.Nghttp2Backend","page":"API Reference","text":"Nghttp2Backend <: AbstractHTTP2Backend\n\nHTTP/2 backend backed by the nghttp2 C library through Nghttp2Wrapper.jl.\n\nNghttp2Wrapper is an optional dependency. Load it before constructing the backend:\n\nusing gRPCServer, Nghttp2Wrapper\nserver = GRPCServer(\"127.0.0.1\", 50051; http2_backend = Nghttp2Backend())\n\nSupported RPC types\n\nUnary and client-streaming calls only. Nghttp2Wrapper's server handler receives a fully buffered request and returns a fully buffered response, so a handler cannot emit messages as it produces them — server-streaming and bidirectional calls are rejected at dispatch rather than silently truncated. Its ROADMAP Milestone 7 tracks the incremental handler that would lift this.\n\nSelect HTTPjlBackend for the full set.\n\n\n\n\n\n","title":"gRPCServer.Nghttp2Backend"},{"category":"type","location":"api/#gRPCServer.BackendCapabilities","page":"API Reference","text":"BackendCapabilities\n\nDeclares which features an HTTP/2 backend supports. Every field defaults to true; a backend declares false for the features it cannot honor. Custom backends get the all-true default unless they define backend_capabilities for their type.\n\nFields (all Bool)\n\ntls: TLS cert/key\ntls_mtls: mutual TLS (client_ca, require_client_cert)\ntls_min_version: minimum TLS version selection\ntls_alpn: ALPN protocol list\ntls_handshake_timeout: per-handshake timeout\ntls_reload: reload_tls!\nmax_connections: max_connections config\nmax_concurrent_streams: max_concurrent_streams config\nqueued_requests: max_queued_requests config\nkeepalive: keepalive_interval / keepalive_timeout config\nconnection_timeouts: idle_timeout / read_header_timeout / read_timeout / write_timeout\nlistener_knobs: max_header_bytes / reuseaddr / backlog\nhttp2_settings: h2_initial_window_size / h2_connection_window_size\ndrain_timeout_config: drain_timeout config field (vs. stop!(; timeout=))\nreceive_cap: max_receive_message_length enforcement\ndecompression: receive-side decompression (informational)\nsend_compression: send-side compression (compression_enabled / compression_threshold / supported_codecs)\nserver_streaming: server-streaming RPCs (informational)\nbidi_streaming: bidi-streaming RPCs (informational)\nreflection: the reflection service (enable_reflection)\nhealth: the health service (enable_health_check)\n\n\n\n\n\n","title":"gRPCServer.BackendCapabilities"},{"category":"function","location":"api/#gRPCServer.backend_capabilities","page":"API Reference","text":"backend_capabilities(backend) -> BackendCapabilities\n\nReturn the capability declaration for a backend type (or instance). Custom backends default to all-true; built-in backends declare the features they cannot honor. Keyed on the type, so backend_capabilities(Nghttp2Backend) works even when the Nghttp2Wrapper extension is not loaded.\n\n\n\n\n\n","title":"gRPCServer.backend_capabilities"},{"category":"function","location":"api/#gRPCServer.backend_defaults","page":"API Reference","text":"backend_defaults(backend) -> NamedTuple\n\nPer-backend default values for the GRPCServer configuration keywords. The default implementation derives the values from a fresh ServerConfig() (single source of truth — no duplicated literals), plus the two h2-window keywords that are GRPCServer-level (65535 = the HTTP.jl HTTP2Settings defaults). A backend may override this method to declare genuinely different effective defaults; for the built-in backends the values are identical today, and the per-backend difference (what raises when explicitly set) lives in backend_capabilities.\n\n\n\n\n\n","title":"gRPCServer.backend_defaults"},{"category":"function","location":"api/#gRPCServer.GRPCServerHTTPJl","page":"API Reference","text":"GRPCServerHTTPJl(host, port; kwargs...) -> GRPCServer\n\nCreate a gRPC server on the HTTP.jl backend (HTTPjlBackend).\n\nAccepts the same configuration keywords as GRPCServer; the backend is fixed to HTTPjlBackend. Explicitly setting a keyword this backend cannot honor raises UnsupportedFeatureError at construction. On this backend the following keywords raise (explicitly set): max_connections, max_queued_requests, keepalive_interval, keepalive_timeout, drain_timeout (pass timeout= to stop! instead), compression_enabled=true, compression_threshold, supported_codecs; reload_tls! also raises on this backend. max_concurrent_streams is supported (default 100, enforced per connection by HTTP.jl).\n\nExample\n\nserver = GRPCServerHTTPJl(\"0.0.0.0\", 50051; max_receive_message_length=8 * 1024 * 1024)\n\n\n\n\n\n","title":"gRPCServer.GRPCServerHTTPJl"},{"category":"function","location":"api/#gRPCServer.GRPCServerPureHTTP2","page":"API Reference","text":"GRPCServerPureHTTP2(host, port; kwargs...) -> GRPCServer\n\nCreate a gRPC server on the pure-Julia HTTP/2 backend (PureHTTP2Backend).\n\nPureHTTP2 is an optional dependency: load it before constructing the server (via using PureHTTP2, which also loads the gRPCServerPureHTTP2Ext extension), or constructing this entry point throws an actionable ArgumentError.\n\nAccepts the same configuration keywords as GRPCServer; the backend is fixed to PureHTTP2Backend. Explicitly setting a keyword this backend cannot honor raises UnsupportedFeatureError at construction. On this backend the following keywords raise (explicitly set): max_connections, max_concurrent_streams, max_queued_requests, keepalive_interval, keepalive_timeout, idle_timeout, read_header_timeout, read_timeout, write_timeout, max_header_bytes, reuseaddr, backlog, h2_initial_window_size, h2_connection_window_size, max_receive_message_length, compression_enabled=true, compression_threshold, supported_codecs. drain_timeout is supported.\n\nExample\n\nusing PureHTTP2\nserver = GRPCServerPureHTTP2(\"0.0.0.0\", 50051; drain_timeout=60.0)\n\n\n\n\n\n","title":"gRPCServer.GRPCServerPureHTTP2"},{"category":"function","location":"api/#gRPCServer.GRPCServerNghttp2","page":"API Reference","text":"GRPCServerNghttp2(host, port; kwargs...) -> GRPCServer\n\nCreate a gRPC server on the Nghttp2 backend (Nghttp2Backend).\n\nAccepts the same configuration keywords as GRPCServer; the backend is fixed to Nghttp2Backend. Requires the Nghttp2Wrapper extension to be loaded (otherwise constructing Nghttp2Backend throws). Explicitly setting a keyword this backend cannot honor raises UnsupportedFeatureError at construction: TLS is supported (cert/key only — mTLS, min_version, alpn_protocols, handshake_timeout_ns raise), enable_health_check is supported (Check works; Watch is refused per-request), and everything else configurable raises when explicitly set (enable_reflection, the timeouts, listener knobs, h2 windows, keepalive, connection limits, message-length limits, and send-side compression).\n\n\n\n\n\n","title":"gRPCServer.GRPCServerNghttp2"},{"category":"type","location":"api/#gRPCServer.AbstractGRPCStream","page":"API Reference","text":"AbstractGRPCStream\n\nRepresents a single in-flight gRPC call (one HTTP/2 stream) as seen by the gRPC dispatch layer, independent of which HTTP/2 backend produced it.\n\nA backend adapter presents each incoming call as an AbstractGRPCStream and implements the stream operations: grpc_path, grpc_method, request_metadata, read_message!, is_cancelled, send_response_headers!, send_message!, send_trailers!, and reset!.\n\n\n\n\n\n","title":"gRPCServer.AbstractGRPCStream"},{"category":"function","location":"api/#gRPCServer.serve_grpc","page":"API Reference","text":"serve_grpc(backend::AbstractHTTP2Backend, server, on_call) -> Nothing\n\nOwn the accept loop for server and invoke on_call(stream::AbstractGRPCStream) once per incoming gRPC call. Backends must validate the HTTP/2 connection preface (h2c) and/or negotiate ALPN h2 (TLS), surface each request's :path and metadata via the stream, honor graceful shutdown when the server leaves the RUNNING state, and fail fast (before accepting traffic) when the backend cannot serve gRPC HTTP/2.\n\nThis is the higher-level extension point that complements create_connection; see the HTTP/2 Backends documentation for details.\n\n\n\n\n\n","title":"gRPCServer.serve_grpc"},{"category":"section","location":"examples/03_sum_numbers/#Sum-Numbers-Client-Streaming-RPC","page":"Sum Numbers","text":"This example demonstrates client streaming RPC, where the client sends multiple requests and receives a single response after all requests are processed.","title":"Sum Numbers - Client Streaming RPC"},{"category":"section","location":"examples/03_sum_numbers/#What-You'll-Learn","page":"Sum Numbers","text":"Defining a proto service with client streaming RPC\nImplementing a client streaming handler using ClientStream{T}\nIterating over incoming requests\nReturning a single aggregated response","title":"What You'll Learn"},{"category":"section","location":"examples/03_sum_numbers/#Proto-Definition","page":"Sum Numbers","text":"// sum.proto\nsyntax = \"proto3\";\npackage math;\n\nservice Math {\n  // Client streaming: stream of requests → single response\n  rpc Sum (stream SumRequest) returns (SumResponse);\n}\n\nmessage SumRequest {\n  double value = 1;\n}\n\nmessage SumResponse {\n  double total = 1;\n  int32 count = 2;\n}\n\nThe stream keyword before SumRequest indicates the client sends multiple messages.","title":"Proto Definition"},{"category":"section","location":"examples/03_sum_numbers/#Server-Implementation","page":"Sum Numbers","text":"using gRPCServer\n\n# Include generated types\ninclude(\"generated/math/math.jl\")\nusing .math\n\n# Client streaming handler - receives multiple requests, returns single response\nfunction sum_handler(ctx::ServerContext, stream::ClientStream{SumRequest})\n    total = 0.0\n    count = 0\n\n    @info \"Starting to receive numbers\" request_id=ctx.request_id\n\n    for request in stream\n        if is_cancelled(ctx)\n            @warn \"Stream cancelled by client\"\n            break\n        end\n        total += request.value\n        count += 1\n        @debug \"Received value\" value=request.value running_total=total\n    end\n\n    @info \"Sum complete\" total=total count=count request_id=ctx.request_id\n    return SumResponse(total, count)\nend\n\n# Register the service with the codegen registration function\nfunction main()\n    host = \"127.0.0.1\"\n    port = 50053\n    server = GRPCServer(host, port;\n        enable_health_check = true,\n        enable_reflection = true\n    )\n\n    register_Math!(server; Sum = sum_handler)\n\n    @info \"gRPC server starting (client streaming example)\" host=host port=port\n    run(server)\nend\n\nmain()\n\nEquivalent form — the per-RPC do-block registration:\n\nregister_Math_Sum!(server) do ctx, stream\n    total = 0.0\n    for request in stream\n        total += request.value\n    end\n    SumResponse(total, 0)\nend","title":"Server Implementation"},{"category":"section","location":"examples/03_sum_numbers/#Key-Concepts","page":"Sum Numbers","text":"","title":"Key Concepts"},{"category":"section","location":"examples/03_sum_numbers/#Client-Streaming-Handler-Signature","page":"Sum Numbers","text":"function handler(ctx::ServerContext, stream::ClientStream{RequestType})\n    for request in stream\n        # Process each request\n    end\n    return ResponseType(...)  # Single response\nend\n\nReceives ClientStream{T} instead of a single request\nIterates over stream with for request in stream\nReturns response directly (not via stream)\nCheck is_cancelled(ctx) to stop early if the client disconnects","title":"Client Streaming Handler Signature"},{"category":"section","location":"examples/03_sum_numbers/#Registration","page":"Sum Numbers","text":"The generated register_Math! accepts the handler as Sum = sum_handler; handler signatures are validated at registration time. The generated client stub for this RPC is Math_Sum_Client.","title":"Registration"},{"category":"section","location":"examples/03_sum_numbers/#Testing","page":"Sum Numbers","text":"","title":"Testing"},{"category":"section","location":"examples/03_sum_numbers/#Run-the-Server","page":"Sum Numbers","text":"cd examples/03_sum_numbers\njulia --project=../.. server.jl","title":"Run the Server"},{"category":"section","location":"examples/03_sum_numbers/#Stream-Numbers-with-grpcurl","page":"Sum Numbers","text":"Client streaming requires stdin piping:\n\necho '{\"value\": 1}\n{\"value\": 2}\n{\"value\": 3}\n{\"value\": 4}\n{\"value\": 5}' | grpcurl -plaintext -d @ localhost:50053 math.Math/Sum\n\nExpected output:\n\n{\n  \"total\": 15,\n  \"count\": 5\n}","title":"Stream Numbers with grpcurl"},{"category":"section","location":"examples/03_sum_numbers/#Empty-Stream","page":"Sum Numbers","text":"echo '' | grpcurl -plaintext -d @ localhost:50053 math.Math/Sum\n\nReturns {\"total\": 0, \"count\": 0}.","title":"Empty Stream"},{"category":"section","location":"examples/03_sum_numbers/#Use-Cases","page":"Sum Numbers","text":"Client streaming is ideal for:\n\nBatch uploads: Sending multiple records and getting a summary\nAggregation: Computing statistics over streamed data\nFile uploads: Streaming file chunks and getting confirmation\nSensor data: Collecting measurements and returning analysis","title":"Use Cases"},{"category":"section","location":"examples/03_sum_numbers/#Next-Steps","page":"Sum Numbers","text":"Proceed to Chat to learn about bidirectional streaming, where both client and server send multiple messages.","title":"Next Steps"},{"category":"section","location":"examples/02_hello_stream/#Hello-Stream-Server-Streaming-RPC","page":"Hello Stream","text":"This example builds on 01_hello_world by adding server streaming, where a single request receives multiple responses over time.","title":"Hello Stream - Server Streaming RPC"},{"category":"section","location":"examples/02_hello_stream/#What-You'll-Learn","page":"Hello Stream","text":"Adding a streaming RPC method to a proto service\nImplementing a server streaming handler\nUsing ServerStream to send multiple responses\nHandling client cancellation","title":"What You'll Learn"},{"category":"section","location":"examples/02_hello_stream/#Proto-Definition","page":"Hello Stream","text":"// greeter.proto\nsyntax = \"proto3\";\npackage helloworld;\n\nservice Greeter {\n  rpc SayHello (HelloRequest) returns (HelloReply);\n  rpc SayHelloStream (HelloRequest) returns (stream HelloReply);\n}\n\nmessage HelloRequest {\n  string name = 1;\n}\n\nmessage HelloReply {\n  string message = 1;\n}\n\nThe stream keyword before HelloReply indicates this method returns multiple responses.","title":"Proto Definition"},{"category":"section","location":"examples/02_hello_stream/#Server-Implementation","page":"Hello Stream","text":"using gRPCServer\n\n# Include generated types\ninclude(\"generated/helloworld/helloworld.jl\")\nusing .helloworld\n\n# Handlers\nfunction say_hello(ctx::ServerContext, request::HelloRequest)::HelloReply\n    @info \"Received request\" name=request.name request_id=ctx.request_id\n    HelloReply(\"Hello, $(request.name)!\")\nend\n\nfunction say_hello_stream(\n    ctx::ServerContext,\n    request::HelloRequest,\n    stream::ServerStream{HelloReply}\n)::Nothing\n    for i in 1:5\n        if is_cancelled(ctx)\n            @warn \"Stream cancelled by client\"\n            return nothing\n        end\n        send!(stream, HelloReply(\"Hello $(i), $(request.name)!\"))\n        sleep(0.5)\n    end\n    return nothing\nend\n\n# Register the service with the codegen registration function\nfunction main()\n    host = \"127.0.0.1\"\n    port = 50051\n    server = GRPCServer(host, port;\n        enable_health_check = true,\n        enable_reflection = true\n    )\n\n    register_Greeter!(server; SayHello = say_hello, SayHelloStream = say_hello_stream)\n\n    @info \"gRPC server starting\" host=host port=port\n    run(server)\nend\n\nmain()","title":"Server Implementation"},{"category":"section","location":"examples/02_hello_stream/#Key-Concepts","page":"Hello Stream","text":"","title":"Key Concepts"},{"category":"section","location":"examples/02_hello_stream/#Streaming-Handler-Signature","page":"Hello Stream","text":"Server streaming handlers receive an additional parameter:\n\nfunction handler(\n    ctx::ServerContext,\n    request::RequestType,\n    stream::ServerStream{ResponseType}\n)::Nothing\n\nThe handler returns Nothing instead of a response type.","title":"Streaming Handler Signature"},{"category":"section","location":"examples/02_hello_stream/#Sending-Responses","page":"Hello Stream","text":"Use send!(stream, response) to send each response:\n\nfor item in items\n    send!(stream, ResponseType(...))\nend","title":"Sending Responses"},{"category":"section","location":"examples/02_hello_stream/#Cancellation-Handling","page":"Hello Stream","text":"Check is_cancelled(ctx) to detect client cancellation:\n\nif is_cancelled(ctx)\n    @warn \"Client cancelled the stream\"\n    return nothing\nend\n\nThis is important for long-running streams to avoid wasting resources.","title":"Cancellation Handling"},{"category":"section","location":"examples/02_hello_stream/#Registration","page":"Hello Stream","text":"The generated register_Greeter! registers both RPCs in one call:\n\nregister_Greeter!(server; SayHello = say_hello, SayHelloStream = say_hello_stream)\n\nEach keyword accepts a handler or a (handler, raw_request, raw_response) tuple; handler signatures are validated at registration time.","title":"Registration"},{"category":"section","location":"examples/02_hello_stream/#Testing","page":"Hello Stream","text":"","title":"Testing"},{"category":"section","location":"examples/02_hello_stream/#Run-the-Server","page":"Hello Stream","text":"cd examples/02_hello_stream\njulia --project=../.. server.jl","title":"Run the Server"},{"category":"section","location":"examples/02_hello_stream/#Call-Unary-RPC","page":"Hello Stream","text":"grpcurl -plaintext -d '{\"name\": \"Julia\"}' localhost:50051 helloworld.Greeter/SayHello\n\nExpected output:\n\n{\n  \"message\": \"Hello, Julia!\"\n}","title":"Call Unary RPC"},{"category":"section","location":"examples/02_hello_stream/#Call-Streaming-RPC","page":"Hello Stream","text":"grpcurl -plaintext -d '{\"name\": \"Julia\"}' localhost:50051 helloworld.Greeter/SayHelloStream\n\nExpected output (5 messages over ~2.5 seconds):\n\n{\n  \"message\": \"Hello 1, Julia!\"\n}\n{\n  \"message\": \"Hello 2, Julia!\"\n}\n{\n  \"message\": \"Hello 3, Julia!\"\n}\n{\n  \"message\": \"Hello 4, Julia!\"\n}\n{\n  \"message\": \"Hello 5, Julia!\"\n}","title":"Call Streaming RPC"},{"category":"section","location":"examples/02_hello_stream/#Other-Streaming-Patterns","page":"Hello Stream","text":"","title":"Other Streaming Patterns"},{"category":"section","location":"examples/02_hello_stream/#Client-Streaming","page":"Hello Stream","text":"Single response after receiving multiple requests:\n\nfunction handler(ctx::ServerContext, stream::ClientStream{RequestType})\n    for request in stream\n        # Process each request\n    end\n    return ResponseType(...)\nend","title":"Client Streaming"},{"category":"section","location":"examples/02_hello_stream/#Bidirectional-Streaming","page":"Hello Stream","text":"Multiple requests and responses simultaneously:\n\nfunction handler(ctx::ServerContext, stream::BidiStream{RequestType, ResponseType})\n    for request in stream\n        send!(stream, ResponseType(...))\n    end\n    close!(stream)\n    return nothing\nend\n\nBoth patterns are registered the same way through the generated functions — see 03_sum_numbers and 04_chat.","title":"Bidirectional Streaming"},{"category":"section","location":"examples/02_hello_stream/#Next-Steps","page":"Hello Stream","text":"Proceed to Sum Numbers to learn about client streaming, where multiple requests produce a single response.","title":"Next Steps"},{"category":"section","location":"examples/advanced/#Advanced-Topics","page":"Advanced","text":"This page covers production-ready features for gRPCServer.jl: interceptors, TLS, compression, and more.\n\nOrdinary servers are built on the codegen interface: one protojl run emits the message types and per-service registration functions, and you register handlers with the generated register_<Service>! / register_<Service>_<Rpc>! functions. The last section of this page, \"The runtime interface beneath the codegen\", explains the descriptor-based layer those generated functions sit on — reach for it only when you need to build or inspect services manually.","title":"Advanced Topics"},{"category":"section","location":"examples/advanced/#Interceptors","page":"Advanced","text":"Interceptors allow you to add cross-cutting concerns like logging, authentication, and rate limiting. They work the same way whether the service was registered through the generated register_*! functions or the runtime interface.","title":"Interceptors"},{"category":"section","location":"examples/advanced/#Logging-Interceptor","page":"Advanced","text":"host = \"127.0.0.1\"\nport = 50051\nserver = GRPCServer(host, port)\n\nadd_interceptor!(server, LoggingInterceptor(\n    log_requests = true,\n    log_responses = true,\n    log_errors = true\n))","title":"Logging Interceptor"},{"category":"section","location":"examples/advanced/#Metrics-Interceptor","page":"Advanced","text":"request_counter = Ref(0)\nlatencies = Float64[]\n\nadd_interceptor!(server, MetricsInterceptor(\n    on_request = (method, size) -> begin\n        request_counter[] += 1\n    end,\n    on_response = (method, status, duration_ms, size) -> begin\n        push!(latencies, duration_ms)\n    end\n))","title":"Metrics Interceptor"},{"category":"section","location":"examples/advanced/#Custom-Authentication-Interceptor","page":"Advanced","text":"struct AuthInterceptor <: Interceptor\n    valid_tokens::Set{String}\nend\n\nfunction (auth::AuthInterceptor)(\n    ctx::ServerContext,\n    request::Any,\n    info::MethodInfo,\n    next::Function\n)\n    token = get_metadata_string(ctx, \"authorization\")\n\n    if token === nothing || !(token in auth.valid_tokens)\n        throw(GRPCError(\n            StatusCode.UNAUTHENTICATED,\n            \"Invalid or missing authentication token\"\n        ))\n    end\n\n    return next(ctx, request)\nend\n\nadd_interceptor!(server, AuthInterceptor(Set([\"token123\", \"token456\"])))","title":"Custom Authentication Interceptor"},{"category":"section","location":"examples/advanced/#Rate-Limiting-Interceptor","page":"Advanced","text":"mutable struct RateLimitInterceptor <: Interceptor\n    requests_per_second::Int\n    window_start::Float64\n    request_count::Int\nend\n\nRateLimitInterceptor(rps::Int) = RateLimitInterceptor(rps, time(), 0)\n\nfunction (rl::RateLimitInterceptor)(\n    ctx::ServerContext,\n    request::Any,\n    info::MethodInfo,\n    next::Function\n)\n    now = time()\n\n    if now - rl.window_start >= 1.0\n        rl.window_start = now\n        rl.request_count = 0\n    end\n\n    rl.request_count += 1\n\n    if rl.request_count > rl.requests_per_second\n        throw(GRPCError(\n            StatusCode.RESOURCE_EXHAUSTED,\n            \"Rate limit exceeded\"\n        ))\n    end\n\n    return next(ctx, request)\nend\n\nadd_interceptor!(server, RateLimitInterceptor(100))","title":"Rate Limiting Interceptor"},{"category":"section","location":"examples/advanced/#Health-Checking","page":"Advanced","text":"Health checks allow load balancers and orchestrators to monitor server status.\n\nserver = GRPCServer(host, port;\n    enable_health_check = true\n)\n\n# Set overall server health\nset_health!(server, HealthStatus.SERVING)\n\n# Set health for specific service\nset_health!(server, \"my.Service\", HealthStatus.SERVING)\n\n# Mark service as not ready (e.g., during maintenance)\nset_health!(server, \"my.Service\", HealthStatus.NOT_SERVING)","title":"Health Checking"},{"category":"section","location":"examples/advanced/#Testing-Health-Check","page":"Advanced","text":"grpcurl -plaintext -d '{\"service\": \"\"}' localhost:50051 grpc.health.v1.Health/Check\n\nExpected output:\n\n{\n  \"status\": \"SERVING\"\n}","title":"Testing Health Check"},{"category":"section","location":"examples/advanced/#TLS-Configuration","page":"Advanced","text":"","title":"TLS Configuration"},{"category":"section","location":"examples/advanced/#Basic-TLS","page":"Advanced","text":"tls_config = TLSConfig(\n    cert_chain = \"server.crt\",\n    private_key = \"server.key\"\n)\n\nserver = GRPCServer(host, port; tls = tls_config)","title":"Basic TLS"},{"category":"section","location":"examples/advanced/#Mutual-TLS-(mTLS)","page":"Advanced","text":"tls_config = TLSConfig(\n    cert_chain = \"server.crt\",\n    private_key = \"server.key\",\n    client_ca = \"ca.crt\",\n    require_client_cert = true\n)\n\nserver = GRPCServer(host, port; tls = tls_config)","title":"Mutual TLS (mTLS)"},{"category":"section","location":"examples/advanced/#Hot-Reloading-Certificates","page":"Advanced","text":"# Reload certificates without restarting server\nreload_tls!(server)\n\nSee the TLS page for a full walkthrough.","title":"Hot Reloading Certificates"},{"category":"section","location":"examples/advanced/#Compression","page":"Advanced","text":"","title":"Compression"},{"category":"section","location":"examples/advanced/#Server-side-Compression-(not-yet-implemented)","page":"Advanced","text":"Send-side response compression is not yet implemented on any backend: responses are always sent with grpc-encoding: identity. The configuration keywords for it (compression_enabled=true, compression_threshold, supported_codecs) are recognized but inert, so setting them explicitly now raises UnsupportedFeatureError at construction instead of being silently ignored:\n\n# Raises UnsupportedFeatureError on every backend — send-side compression\n# is not implemented yet.\nserver = GRPCServer(host, port;\n    supported_codecs = [CompressionCodec.GZIP, CompressionCodec.DEFLATE]\n)\n\nOmit those keywords for now. Receive-side decompression works: the server accepts grpc-encoding: gzip/deflate requests and decompresses them (strictly on HTTPjlBackend, leniently on PureHTTP2Backend), so compressed clients are fully supported.","title":"Server-side Compression (not yet implemented)"},{"category":"section","location":"examples/advanced/#Manual-Compression","page":"Advanced","text":"using gRPCServer: compress, decompress, CompressionCodec\n\ndata = Vector{UInt8}(\"Large data to compress...\")\n\n# Compress with GZIP\ncompressed = compress(data, CompressionCodec.GZIP)\n\n# Decompress\noriginal = decompress(compressed, CompressionCodec.GZIP)","title":"Manual Compression"},{"category":"section","location":"examples/advanced/#Error-Handling","page":"Advanced","text":"","title":"Error Handling"},{"category":"section","location":"examples/advanced/#Returning-Specific-Status-Codes","page":"Advanced","text":"function my_handler(ctx::ServerContext, request)\n    if request.id < 0\n        throw(GRPCError(\n            StatusCode.INVALID_ARGUMENT,\n            \"ID must be non-negative\"\n        ))\n    end\n\n    item = find_item(request.id)\n    if item === nothing\n        throw(GRPCError(\n            StatusCode.NOT_FOUND,\n            \"Item not found: $(request.id)\"\n        ))\n    end\n\n    if !has_permission(ctx, item)\n        throw(GRPCError(\n            StatusCode.PERMISSION_DENIED,\n            \"Access denied to item $(request.id)\"\n        ))\n    end\n\n    return item\nend","title":"Returning Specific Status Codes"},{"category":"section","location":"examples/advanced/#Error-Details","page":"Advanced","text":"throw(GRPCError(\n    StatusCode.INVALID_ARGUMENT,\n    \"Multiple validation errors\",\n    Any[\n        Dict(\"field\" => \"email\", \"error\" => \"Invalid email format\"),\n        Dict(\"field\" => \"age\", \"error\" => \"Must be positive\")\n    ]\n))","title":"Error Details"},{"category":"section","location":"examples/advanced/#Context-Usage","page":"Advanced","text":"","title":"Context Usage"},{"category":"section","location":"examples/advanced/#Accessing-Metadata","page":"Advanced","text":"function my_handler(ctx::ServerContext, request)\n    # Get string metadata\n    auth = get_metadata_string(ctx, \"authorization\")\n\n    # Get binary metadata (keys ending in -bin)\n    trace = get_metadata_binary(ctx, \"x-trace-bin\")\n\n    # Check remaining time before deadline\n    remaining = remaining_time(ctx)\n    if remaining !== nothing && remaining < 1.0\n        @warn \"Less than 1 second remaining\"\n    end\n\n    return response\nend","title":"Accessing Metadata"},{"category":"section","location":"examples/advanced/#Setting-Response-Headers-and-Trailers","page":"Advanced","text":"function my_handler(ctx::ServerContext, request)\n    # Set response header\n    set_header!(ctx, \"x-request-id\", string(ctx.request_id))\n\n    # Set trailer (sent at end of response)\n    set_trailer!(ctx, \"x-processing-time\", \"50ms\")\n\n    return response\nend","title":"Setting Response Headers and Trailers"},{"category":"section","location":"examples/advanced/#Client-Streaming","page":"Advanced","text":"A service that receives multiple requests and returns a single response, registered with the generated codegen function:\n\nfunction sum_numbers(ctx::ServerContext, stream::ClientStream{NumberRequest})\n    total = 0\n    for request in stream\n        total += request.value\n    end\n    return SumResponse(total = total)\nend\n\n# do-block per-RPC form\nregister_Math_Sum!(server) do ctx, stream\n    total = 0\n    for request in stream\n        total += request.value\n    end\n    SumResponse(total = total)\nend","title":"Client Streaming"},{"category":"section","location":"examples/advanced/#Bidirectional-Streaming","page":"Advanced","text":"A chat-like service with two-way streaming:\n\nfunction chat(ctx::ServerContext, stream::BidiStream{ChatMessage, ChatMessage})\n    for message in stream\n        if is_cancelled(ctx)\n            break\n        end\n        # Echo back with prefix\n        response = ChatMessage(\n            user = \"Server\",\n            text = \"You said: $(message.text)\"\n        )\n        send!(stream, response)\n    end\n    close!(stream)\n    return nothing\nend\n\n# do-block per-RPC form\nregister_Chat_Chat!(server) do ctx, stream\n    for message in stream\n        send!(stream, ChatMessage(\"Server\", \"You said: $(message.text)\"))\n    end\n    close!(stream)\n    return nothing\nend","title":"Bidirectional Streaming"},{"category":"section","location":"examples/advanced/#Passing-Application-State","page":"Advanced","text":"Attach application state to the server and read it from any handler through ctx.payload:\n\nstruct AppState\n    db\nend\n\nserver = GRPCServer(\"127.0.0.1\", 50051; context = AppState(open_db()))\n\nregister_MyService_GetThing!(server) do ctx, req\n    Thing(query(ctx.payload.db, req.id))\nend\n\nThe context keyword accepts any value; it is threaded untouched into every request's ServerContext.payload. Handlers never construct the state themselves, which makes them easy to test in isolation.","title":"Passing Application State"},{"category":"section","location":"examples/advanced/#Concurrency-Model","page":"Advanced","text":"The server is built on HTTP.jl, which spawns one task per inbound HTTP/2 stream. That per-stream task is where your handler runs. Because each connection and each stream is independent, many RPCs are served concurrently as a matter of course.\n\nThe max_concurrent_requests keyword on GRPCServer (default 1024) caps how many RPCs run at once. When the cap is reached, additional requests are shed immediately with a trailers-only StatusCode.RESOURCE_EXHAUSTED status — there is no queue and no waiting. Pass nothing or 0 for an unlimited cap (the legacy csvance behavior).\n\nserver = GRPCServer(\"127.0.0.1\", 50051;\n    max_concurrent_requests = 256\n)\n\nHandler thread safety is the application's responsibility: two handlers can execute simultaneously on different threads and share whatever you attached as context. Guard mutable shared state (database connection pools, caches, counters) with the appropriate locks or atomics. For CPU-bound work, launch Julia with --threads=auto; with a single thread, tasks still interleave cooperatively at I/O boundaries, but CPU-bound handlers will not run in parallel.","title":"Concurrency Model"},{"category":"section","location":"examples/advanced/#Production-Hardening","page":"Advanced","text":"","title":"Production Hardening"},{"category":"section","location":"examples/advanced/#Authentication-and-authorization","page":"Advanced","text":"Authentication and authorization are the application's responsibility. The server does not authenticate callers. A handler reads credentials from request metadata and rejects the call with the appropriate status:\n\nfunction my_handler(ctx::ServerContext, request)\n    token = get_metadata_string(ctx, \"authorization\")\n    if token === nothing || !is_valid(token)\n        throw(GRPCError(StatusCode.UNAUTHENTICATED, \"Missing or invalid credentials\"))\n    end\n    if !authorized(token, request)\n        throw(GRPCError(StatusCode.PERMISSION_DENIED, \"Access denied\"))\n    end\n    return response\nend","title":"Authentication and authorization"},{"category":"section","location":"examples/advanced/#Transport","page":"Advanced","text":"Use TLS in production. The default is cleartext HTTP/2 (h2c); pass tls = TLSConfig(...) to serve h2. Cleartext should only be used behind a trusted boundary, for example a localhost sidecar or a TLS-terminating proxy. See TLS.","title":"Transport"},{"category":"section","location":"examples/advanced/#Concurrency-cap","page":"Advanced","text":"max_concurrent_requests ships enabled with a conservative default of 1024 (HTTP.jl allows 100 concurrent streams per connection, so without a cap N connections imply 100·N concurrent handler tasks). Still size it explicitly to the host's memory and the configured max_message_size in production; a cap that is too small sheds legitimate load with RESOURCE_EXHAUSTED, while one that is too large lets a flood consume all available memory.","title":"Concurrency cap"},{"category":"section","location":"examples/advanced/#Connection-timeouts","page":"Advanced","text":"Connection timeouts default to read_header_timeout = 30 seconds, which reaps slow-header connections without disturbing established streams, and idle_timeout = 300 seconds, which closes connections that stop sending bytes (including one holding a partial request body, bounding slow-body memory accrual). read_timeout and write_timeout are disabled by default; enabling them defends against a peer that trickles or never finishes a request or response body, but a non-zero read_timeout also terminates legitimately idle long-lived streaming RPCs, so set it only for unary or short-lived workloads.","title":"Connection timeouts"},{"category":"section","location":"examples/advanced/#Deadlines-and-cancellation","page":"Advanced","text":"The grpc-timeout header is parsed strictly into ctx.deadline (a malformed value fails the call with INVALID_ARGUMENT). The deadline is enforced at two points, and never while your handler is running:\n\nPre-dispatch: if the deadline has already passed when the request reaches\n\nthe handler (a zero timeout, or queueing delay past the deadline), the call fails fast with a trailers-only DEADLINE_EXCEEDED and your handler is never invoked.\n\nPost-return: once your handler returns, a deadline that has since passed\n\nmaps the result to DEADLINE_EXCEEDED (a status your handler already produced as DEADLINE_EXCEEDED/CANCELLED is left untouched).\n\nA handler that runs past its deadline is not interrupted — it runs to completion, and only then is its result mapped. There is no watchdog-based cancellation yet. Handlers that must bound their own runtime should check remaining_time(ctx) / is_cancelled(ctx) cooperatively (the gRPC interceptors work here too — see TimeoutInterceptor, which is also pre-check-only):\n\nfunction my_handler(ctx::ServerContext, request)\n    remaining = remaining_time(ctx)\n    if remaining !== nothing && remaining <= 0\n        throw(GRPCError(StatusCode.DEADLINE_EXCEEDED, \"Deadline exceeded\"))\n    end\n    # ... work, checking is_cancelled(ctx) between long steps\nend\n\nA long-running handler that ignores the deadline is a resource-exhaustion vector: it ties up a stream (and memory) for as long as it runs. Pair cooperative deadline checks with a max_concurrent_requests cap sized to your workload, and keep idle_timeout enabled, so that a flood of slow or never-completing calls cannot pile up unbounded handlers.","title":"Deadlines and cancellation"},{"category":"section","location":"examples/advanced/#The-Runtime-Interface-Beneath-the-Codegen","page":"Advanced","text":"The generated register_<Service>_<Rpc>! functions build a MethodDescriptor and call register_method! on the server's dispatcher. You normally never do this by hand, but the pieces are public so custom registration flows are possible.","title":"The Runtime Interface Beneath the Codegen"},{"category":"section","location":"examples/advanced/#Descriptor-builders","page":"Advanced","text":"Each *_Method builder creates a MethodDescriptor for one RPC:\n\nmethod = MyService_GetThing_Method((ctx, req) -> Thing(req.id))\n\n# raw variants: receive/return undecoded Vector{UInt8} payloads\nmethod = MyService_GetThing_Method((ctx, raw) -> raw; raw_request = true, raw_response = true)","title":"Descriptor builders"},{"category":"section","location":"examples/advanced/#Manual-service-registration","page":"Advanced","text":"Build a ServiceDescriptor and register it with register!, or register a single method with register_method!:\n\nstruct MyService end\n\nfunction gRPCServer.service_descriptor(::MyService)\n    ServiceDescriptor(\n        \"pkg.MyService\",\n        Dict(\n            \"GetThing\" => MyService_GetThing_Method((ctx, req) -> Thing(req.id))\n        ),\n        nothing\n    )\nend\n\nregister!(server, MyService())\n\n# or, for a single method:\nregister_method!(server.dispatcher, \"pkg.MyService\",\n    MyService_GetThing_Method((ctx, req) -> Thing(req.id)))\n\nregister_method! is what the generated register_*! functions call internally. See the API Reference for the full surface (MethodDescriptor, ServiceDescriptor, register!, register_method!).","title":"Manual service registration"},{"category":"section","location":"examples/advanced/#Graceful-Shutdown","page":"Advanced","text":"server = GRPCServer(host, port)\nregister_Greeter!(server; SayHello = say_hello)\n\n# Run in background task\nserver_task = @async run(server; block = true)\n\n# Later, initiate graceful shutdown\n@info \"Shutting down...\"\nstop!(server; timeout = 30.0)\n\n# Wait for server to stop\nwait(server_task)\n@info \"Server stopped\"","title":"Graceful Shutdown"},{"category":"section","location":"examples/advanced/#Next-Steps","page":"Advanced","text":"API Reference - Complete API documentation\nQuick Start - Getting started guide\nCode Generation - The codegen interface in detail","title":"Next Steps"},{"category":"section","location":"quickstart/#Quick-Start","page":"Quick Start","text":"This guide demonstrates how to create a gRPC server in Julia using gRPCServer.jl.","title":"Quick Start"},{"category":"section","location":"quickstart/#Prerequisites","page":"Quick Start","text":"Julia 1.10 or later\nProtoBuf.jl for message type generation\ngRPCClient.jl (optional, for the generated client stubs)","title":"Prerequisites"},{"category":"section","location":"quickstart/#Installation","page":"Quick Start","text":"using Pkg\nPkg.add(\"gRPCServer\")","title":"Installation"},{"category":"section","location":"quickstart/#Step-1:-Define-Your-Service","page":"Quick Start","text":"This example is based on examples/01_hello_world (basic unary) and examples/02_hello_stream (streaming).\n\nCreate a .proto file defining your service:\n\n// greeter.proto\nsyntax = \"proto3\";\n\npackage helloworld;\n\nservice Greeter {\n  rpc SayHello (HelloRequest) returns (HelloReply);\n  rpc SayHelloStream (HelloRequest) returns (stream HelloReply);\n}\n\nmessage HelloRequest {\n  string name = 1;\n}\n\nmessage HelloReply {\n  string message = 1;\n}","title":"Step 1: Define Your Service"},{"category":"section","location":"quickstart/#Step-2:-Generate-Julia-Types","page":"Quick Start","text":"Use ProtoBuf.jl to generate Julia types directly from the .proto file (no external tools needed). Load both gRPCServer and gRPCClient first — one protojl run then emits the message types, the gRPCClient.jl client stubs, and the gRPCServer.jl registration functions together:\n\nusing ProtoBuf\nusing gRPCServer\nimport gRPCClient\n\n# Generate Julia structs from proto file\n# Arguments: proto_file, search_path, output_directory\nprotojl(\"greeter.proto\", \".\", \"generated\";\n    always_use_modules = true,\n    add_kwarg_constructors = true\n)\n\nThis creates the following file structure:\n\ngenerated/\n└── helloworld/\n    ├── helloworld.jl      # Module wrapper\n    └── greeter_pb.jl      # Messages + client stubs + registration functions\n\nWithin greeter_pb.jl, the # gRPCClient.jl BEGIN/END block defines the Greeter_*_Client client constructors, and the # gRPCServer.jl BEGIN/END block defines the Greeter_*_Method descriptor builders and the register_Greeter_SayHello!/register_Greeter_SayHelloStream!/register_Greeter! registration functions.\n\nRegenerate whenever you change the .proto file.","title":"Step 2: Generate Julia Types"},{"category":"section","location":"quickstart/#Step-3:-Implement-Handlers","page":"Quick Start","text":"using gRPCServer\ninclude(\"generated/helloworld/helloworld.jl\")\nusing .helloworld\n\n# Unary RPC handler\nfunction say_hello(ctx::ServerContext, request::HelloRequest)::HelloReply\n    name = isempty(request.name) ? \"World\" : request.name\n    return HelloReply(message = \"Hello, $(name)!\")\nend\n\n# Server streaming RPC handler\nfunction say_hello_stream(\n    ctx::ServerContext,\n    request::HelloRequest,\n    stream::ServerStream{HelloReply}\n)::Nothing\n    name = isempty(request.name) ? \"World\" : request.name\n    for i in 1:5\n        if is_cancelled(ctx)\n            @warn \"Stream cancelled by client\"\n            return nothing\n        end\n        send!(stream, HelloReply(message = \"Hello $(i), $(name)!\"))\n        sleep(0.5)  # Simulate work\n    end\n    return nothing\nend\n\nEvery handler receives the request context first. The four handler contracts are:\n\nRPC type Handler signature\nUnary (ctx::ServerContext, req::TReq) -> TResp\nServer streaming (ctx, req::TReq, stream::ServerStream{TResp}) -> Nothing — send with send!(stream, msg)\nClient streaming (ctx, stream::ClientStream{TReq}) -> TResp — iterate with for req in stream\nBidirectional (ctx, stream::BidiStream{TReq, TResp}) -> Nothing — iterate and send!(stream, msg)","title":"Step 3: Implement Handlers"},{"category":"section","location":"quickstart/#Step-4:-Register-Handlers","page":"Quick Start","text":"The generated registration functions replace any hand-written service descriptor. Use the per-RPC do-block form:\n\nregister_Greeter_SayHello!(server) do ctx, req\n    HelloReply(message = \"Hello, $(req.name)!\")\nend\n\nregister_Greeter_SayHelloStream!(server) do ctx, req, stream\n    for i in 1:5\n        send!(stream, HelloReply(message = \"Hello $(i), $(req.name)!\"))\n    end\n    return nothing\nend\n\nor with named functions:\n\nregister_Greeter_SayHello!(server, say_hello)\nregister_Greeter_SayHelloStream!(server, say_hello_stream)\n\nor register several RPCs of a service at once with the aggregate form:\n\nregister_Greeter!(server; SayHello = say_hello, SayHelloStream = say_hello_stream)\n\nEach keyword accepts a handler or a (handler, raw_request, raw_response) tuple. Handler signatures are validated at registration time — a mismatched shape throws an ArgumentError.","title":"Step 4: Register Handlers"},{"category":"section","location":"quickstart/#Step-5:-Create-and-Run-Server","page":"Quick Start","text":"# Create server\nhost = \"127.0.0.1\"\nport = 50051\nserver = GRPCServer(host, port)\n\n# Register service\nregister_Greeter!(server; SayHello = say_hello, SayHelloStream = say_hello_stream)\n\n# Start server (blocking)\n@info \"Starting gRPC server\" host=host port=port\nrun(server)\n\nWhen the server starts successfully, you'll see:\n\n[ Info: gRPC server starting\n│   host = \"127.0.0.1\"\n│   port = 50051\n\nThe server is now listening for connections. Keep this terminal running.","title":"Step 5: Create and Run Server"},{"category":"section","location":"quickstart/#Complete-Example","page":"Quick Start","text":"Save as server.jl:\n\nusing gRPCServer\n\n# Include generated types\ninclude(\"generated/helloworld/helloworld.jl\")\nusing .helloworld\n\n# Handlers\nfunction say_hello(ctx::ServerContext, request::HelloRequest)::HelloReply\n    @info \"Received request\" name=request.name request_id=ctx.request_id\n    HelloReply(message = \"Hello, $(request.name)!\")\nend\n\nfunction say_hello_stream(\n    ctx::ServerContext,\n    request::HelloRequest,\n    stream::ServerStream{HelloReply}\n)::Nothing\n    for i in 1:5\n        if is_cancelled(ctx)\n            @warn \"Stream cancelled by client\"\n            return nothing\n        end\n        send!(stream, HelloReply(message = \"Hello $(i), $(request.name)!\"))\n        sleep(0.5)\n    end\n    return nothing\nend\n\n# Run server\nfunction main()\n    host = \"127.0.0.1\"  # 0.0.0.0 (risky)\n    port = 50051\n    server = GRPCServer(host, port;\n        enable_health_check = true,\n        enable_reflection = true\n    )\n\n    register_Greeter!(server; SayHello = say_hello, SayHelloStream = say_hello_stream)\n\n    @info \"gRPC server starting\" host=host port=port\n    run(server)\nend\n\nmain()\n\nRun with:\n\njulia server.jl","title":"Complete Example"},{"category":"section","location":"quickstart/#What-Happens-Under-the-Hood","page":"Quick Start","text":"The generated register_Greeter_*! functions build a MethodDescriptor for each RPC and call register_method! on the server's dispatcher. They are thin wrappers over the runtime registration interface — see Code Generation for the emission details and the API Reference for the underlying types. The raw_request/raw_response keyword flags opt a handler into receiving and/or returning undecoded Vector{UInt8} payloads instead of typed messages.","title":"What Happens Under the Hood"},{"category":"section","location":"quickstart/#Testing-with-grpcurl","page":"Quick Start","text":"Note: grpcurl is a command-line tool for interacting with gRPC servers. See the installation instructions for your platform.\n\n# List services (requires reflection enabled)\ngrpcurl -plaintext localhost:50051 list\n\nExpected output:\n\ngrpc.health.v1.Health\ngrpc.reflection.v1alpha.ServerReflection\nhelloworld.Greeter\n\n# Call unary RPC\ngrpcurl -plaintext -d '{\"name\": \"Julia\"}' \\\n  localhost:50051 helloworld.Greeter/SayHello\n\nExpected output:\n\n{\n  \"message\": \"Hello, Julia!\"\n}\n\n# Call streaming RPC\ngrpcurl -plaintext -d '{\"name\": \"Julia\"}' \\\n  localhost:50051 helloworld.Greeter/SayHelloStream\n\nExpected output (5 messages streamed):\n\n{\n  \"message\": \"Hello 1, Julia!\"\n}\n{\n  \"message\": \"Hello 2, Julia!\"\n}\n{\n  \"message\": \"Hello 3, Julia!\"\n}\n{\n  \"message\": \"Hello 4, Julia!\"\n}\n{\n  \"message\": \"Hello 5, Julia!\"\n}","title":"Testing with grpcurl"},{"category":"section","location":"quickstart/#Testing-with-gRPCClient.jl","page":"Quick Start","text":"The same protojl run also generated client stubs. Call gRPCClient.grpc_init() once, then use the generated Greeter_SayHello_Client constructor with grpc_sync_request for unary calls:\n\nusing gRPCServer\ninclude(\"generated/helloworld/helloworld.jl\")\nusing .helloworld\nimport gRPCClient\n\ngRPCClient.grpc_init()\nclient = helloworld.Greeter_SayHello_Client(\"127.0.0.1\", 50051)\n\n# Unary RPC\nresp = gRPCClient.grpc_sync_request(client, helloworld.HelloRequest(name = \"Julia\"))\nprintln(resp.message)  # \"Hello, Julia!\"\n\nFor server streaming, pass a response Channel and iterate it:\n\nresponse_c = Channel{helloworld.HelloReply}(16)\nreq = gRPCClient.grpc_async_request(client, helloworld.HelloRequest(name = \"Julia\"), response_c)\nfor reply in response_c\n    println(reply.message)\nend\ngRPCClient.grpc_async_await(req)\n\nFor client streaming, send requests through a Channel and await the single response; for bidirectional streaming, pass request and response channels (see gRPCClient.jl for the full client API).","title":"Testing with gRPCClient.jl"},{"category":"section","location":"quickstart/#Adding-Interceptors","page":"Quick Start","text":"# Add built-in logging interceptor\nadd_interceptor!(server, LoggingInterceptor())\n\n# Add metrics interceptor with callbacks\nadd_interceptor!(server, MetricsInterceptor(\n    on_request = (method, size) -> increment_counter(\"requests\"),\n    on_response = (method, status, ms, size) -> record_latency(ms)\n))\n\nInterceptors work the same way whether the service was registered through the generated register_*! functions or the runtime interface.","title":"Adding Interceptors"},{"category":"section","location":"quickstart/#Enabling-TLS","page":"Quick Start","text":"host = \"127.0.0.1\"\nport = 50051\ntls_config = TLSConfig(\n    cert_chain = \"/path/to/server.crt\",\n    private_key = \"/path/to/server.key\",\n    client_ca = nothing,          # Set for mTLS\n    require_client_cert = false,\n    min_version = :TLSv1_2,\n    alpn_protocols = [\"h2\"],      # Default; shown for clarity\n)\n\nserver = GRPCServer(host, port;\n    tls = tls_config\n)\n\nSee the TLS documentation page for a full walkthrough including ALPN behavior, mTLS, and certificate reload.","title":"Enabling TLS"},{"category":"section","location":"quickstart/#Error-Handling","page":"Quick Start","text":"function my_handler(ctx::ServerContext, request)\n    if !is_valid(request)\n        throw(GRPCError(\n            StatusCode.INVALID_ARGUMENT,\n            \"Request validation failed\",\n            []\n        ))\n    end\n\n    user = find_user(request.user_id)\n    if user === nothing\n        throw(GRPCError(\n            StatusCode.NOT_FOUND,\n            \"User not found: $(request.user_id)\",\n            []\n        ))\n    end\n\n    return MyResponse(user = user)\nend","title":"Error Handling"},{"category":"section","location":"quickstart/#Graceful-Shutdown","page":"Quick Start","text":"# In a separate task or signal handler\nfunction shutdown(server::GRPCServer)\n    @info \"Initiating graceful shutdown...\"\n    stop!(server; timeout = 30.0)  # Wait up to 30s for in-flight requests\n    @info \"Server stopped\"\nend","title":"Graceful Shutdown"},{"category":"section","location":"code_generation/#Code-Generation","page":"Code Generation","text":"gRPCServer integrates with ProtoBuf.jl through an external code generation handler. Loading the package registers that handler from its __init__ (via grpc_register_service_codegen()), so you do not normally call anything by hand — you just run ProtoBuf.jl's protojl on your .proto files.\n\nWhen gRPCClient.jl is also loaded, a single protojl run emits the message types, the gRPCClient.jl client stubs, and the gRPCServer.jl registration functions into the same generated file.","title":"Code Generation"},{"category":"section","location":"code_generation/#Running-protojl","page":"Code Generation","text":"Load both packages, then run protojl (re-exported by gRPCServer) from your project directory:\n\nusing ProtoBuf\nusing gRPCServer\nimport gRPCClient\n\nprotojl(\"myservice.proto\", \".\", \"generated\";\n    always_use_modules = true,\n    add_kwarg_constructors = true\n)\n\nFor a package myservice; in the proto, this writes:\n\ngenerated/\n└── myservice/\n    ├── myservice.jl      # module wrapper; include() + using .myservice\n    └── myservice_pb.jl   # messages + client stubs + registration functions\n\nThe generated file is delimited into two blocks:\n\n# gRPCClient.jl BEGIN … # gRPCClient.jl END — the <Service>_<Rpc>_Client client constructors (present only when gRPCClient.jl is loaded).\n# gRPCServer.jl BEGIN … # gRPCServer.jl END — the <Service>_<Rpc>_Method descriptor builders, the per-RPC register_<Service>_<Rpc>! functions, and the aggregate register_<Service>! function.\n\nUse the generated module from your server:\n\nusing gRPCServer\ninclude(\"generated/myservice/myservice.jl\")\nusing .myservice\n\nRegenerate whenever you change the .proto file; the output is deterministic (no timestamps or machine-specific paths).","title":"Running protojl"},{"category":"section","location":"code_generation/#Emitted-symbols","page":"Code Generation","text":"For each service in the .proto, gRPCServer emits the following (exact signatures from the generated output):\n\nTyped descriptor builder — one per RPC:\n\n<Service>_<Rpc>_Method(handler; raw_request=false, raw_response=false) -> gRPCServer.MethodDescriptor\n\nPer-RPC registration — emitted in both argument orders, so the do-block\n\nform works:\n\nregister_<Service>_<Rpc>!(server::GRPCServer, handler; raw_request=false, raw_response=false) -> server\nregister_<Service>_<Rpc>!(handler::Function, server::GRPCServer; kwargs...) -> server\n\nPer-service aggregate — registers several RPCs at once by keyword:\n\nregister_<Service>!(server::GRPCServer; <Rpc>=nothing, ...) -> server\n\nEvery non-nothing keyword registers its RPC. Each keyword accepts a handler or a (handler, raw_request, raw_response) tuple (raw flags per method). All-nothing is a no-op. It is equivalent to calling the per-RPC register_<Service>_<Rpc>! functions individually.","title":"Emitted symbols"},{"category":"section","location":"code_generation/#Handler-contracts","page":"Code Generation","text":"The registration functions validate the handler signature at registration time; a mismatched shape throws ArgumentError. The four contracts (context first):\n\nRPC type Handler signature\nUnary (ctx::gRPCServer.ServerContext, req::TReq) -> TResp\nServer streaming (ctx, req::TReq, stream::gRPCServer.ServerStream{TResp}) -> Nothing — send responses with gRPCServer.send!(stream, msg)\nClient streaming (ctx, stream::gRPCServer.ClientStream{TReq}) -> TResp — iterate with for req in stream\nBidirectional (ctx, stream::gRPCServer.BidiStream{TReq, TResp}) -> Nothing — iterate and gRPCServer.send!(stream, msg)","title":"Handler contracts"},{"category":"section","location":"code_generation/#Raw-request-and-response-buffers","page":"Code Generation","text":"The raw_request and raw_response flags override a side with Vector{UInt8}: the handler receives the raw, undecoded protobuf payload and/or returns raw response bytes instead of a typed message. The raw buffer is the protobuf message body only; the gRPC framing is still handled by the library.\n\n# Both sides raw\nregister_myservice_GetThing!(server, (ctx, raw) -> raw;\n    raw_request = true, raw_response = true)","title":"Raw request and response buffers"},{"category":"section","location":"code_generation/#Registration-time-validation","page":"Code Generation","text":"A handler whose signature does not match the RPC's contract (wrong arity, wrong types, or a raw/typed mismatch) raises ArgumentError at register_*! time, before any request is served.","title":"Registration-time validation"},{"category":"section","location":"code_generation/#Under-the-hood","page":"Code Generation","text":"Each generated register_<Service>_<Rpc>! builds a MethodDescriptor via the *_Method builder and calls gRPCServer.register_method! on the server's dispatcher. The runtime interface — register_method!, MethodDescriptor, ServiceDescriptor, register! — is documented in the API Reference; an explicit walkthrough of the underlying layer lives in the Advanced Examples.","title":"Under the hood"},{"category":"section","location":"code_generation/#Next-steps","page":"Code Generation","text":"Quick Start — end-to-end walkthrough\nExamples — five runnable example servers\nTLS — serving codegen-registered services over TLS\nAPI Reference — the runtime interface beneath the codegen","title":"Next steps"},{"category":"section","location":"","page":"Home","text":"<div id=\"landing\" class=\"landing\">\n<header class=\"landing-hero\">\n  <div class=\"landing-hero__text\">\n    <p class=\"landing-name\">gRPCServer.jl</p>\n    <h1 class=\"landing-title\">A production-ready gRPC server in Julia</h1>\n    <p class=\"landing-tagline\">Four RPC patterns. Three backends. One API.</p>\n    <div class=\"landing-actions\">\n<a class=\"landing-btn landing-btn--brand\" href=\"quickstart/\">Quick Start</a>\n      <a class=\"landing-btn landing-btn--alt\" href=\"code_generation/\">Code Generation</a>\n      <a class=\"landing-btn landing-btn--alt\" href=\"https://github.com/JuliaIO/gRPCServer.jl\">View on GitHub</a>\n    </div>\n  </div>\n  <div class=\"landing-hero__image\">\n    <div class=\"landing-hero__image-container\">\n      <img class=\"docs-light-only\" src=\"assets/logo.svg\" alt=\"gRPCServer.jl\" width=\"320\" height=\"320\">\n      <img class=\"docs-dark-only\" src=\"assets/logo-dark.svg\" alt=\"gRPCServer.jl\" width=\"320\" height=\"320\">\n    </div>\n  </div>\n</header>\n<section class=\"landing-features\" aria-label=\"Features\">\n  <a class=\"landing-feature\" href=\"quickstart/\">\n<div class=\"landing-feature__icon\">🧬</div>\n<h2 class=\"landing-feature__title\">All four RPC patterns</h2>\n<p class=\"landing-feature__details\">Unary, server-streaming, client-streaming, and bidirectional streaming over one consistent API.</p>\n  </a>\n  <a class=\"landing-feature\" href=\"http2-backends/\">\n<div class=\"landing-feature__icon\">🔌</div>\n<h2 class=\"landing-feature__title\">Pluggable HTTP/2 backends</h2>\n<p class=\"landing-feature__details\">HTTP.jl is the production-ready default, with two experimental backends behind a pluggable interface.</p>\n  </a>\n  <a class=\"landing-feature\" href=\"performance/\">\n<div class=\"landing-feature__icon\">🛡️</div>\n<h2 class=\"landing-feature__title\">Hardened for production</h2>\n<p class=\"landing-feature__details\">Over a million test assertions across six CI platform combos, nanosecond dispatch benchmarks, and v1.0 deadline, shutdown, and mTLS hardening.</p>\n  </a>\n  <a class=\"landing-feature\" href=\"code_generation/\">\n<div class=\"landing-feature__icon\">⚙️</div>\n<h2 class=\"landing-feature__title\">IDE-first code generation</h2>\n<p class=\"landing-feature__details\">One protojl run emits message types and registration functions designed for IDE code completion and suggestions.</p>\n  </a>\n  <a class=\"landing-feature\" href=\"examples/advanced/\">\n<div class=\"landing-feature__icon\">🧩</div>\n<h2 class=\"landing-feature__title\">Middleware interceptors</h2>\n<p class=\"landing-feature__details\">Logging, metrics, timeout, and recovery interceptors out of the box, plus a clean hook to write your own.</p>\n  </a>\n  <a class=\"landing-feature\" href=\"tls/\">\n<div class=\"landing-feature__icon\">🔐</div>\n<h2 class=\"landing-feature__title\">TLS and mTLS</h2>\n<p class=\"landing-feature__details\">TLSConfig covers certificates, client-CA mTLS, and ALPN.</p>\n  </a>\n  <a class=\"landing-feature\" href=\"api/\">\n<div class=\"landing-feature__icon\">🩺</div>\n<h2 class=\"landing-feature__title\">Health + reflection built in</h2>\n<p class=\"landing-feature__details\">Standard grpc.health.v1 checking and server reflection let grpcurl and standard tooling discover your services.</p>\n  </a>\n  <a class=\"landing-feature\" href=\"performance/\">\n<div class=\"landing-feature__icon\">🗜️</div>\n<h2 class=\"landing-feature__title\">Wire efficiency</h2>\n<p class=\"landing-feature__details\">Strict gzip and deflate request decompression plus zero-copy framing for large payloads.</p>\n  </a>\n</section>\n</div>","title":"Home"},{"category":"section","location":"#What-it-is","page":"Home","text":"gRPCServer.jl is a native Julia gRPC server: the default HTTP.jl backend serves unary and streaming RPCs out of the box, with TLS/mTLS, interceptors, health, and reflection built in. One protojl run generates message types, client stubs, and server registration functions. PureHTTP2 and nghttp2 are optional pluggable backends.","title":"What it is"},{"category":"section","location":"#Getting-started","page":"Home","text":"Quick Start — serve your first RPC in a few lines\nCode Generation — protojl end to end\nHTTP/2 Backends — default HTTP.jl, opt-in PureHTTP2/nghttp2","title":"Getting started"},{"category":"section","location":"#Related-packages","page":"Home","text":"gRPCClient.jl is the sibling client package; load both and a single protojl run emits client stubs alongside the server registration functions.","title":"Related packages"},{"category":"section","location":"#Installation","page":"Home","text":"using Pkg\nPkg.add(\"gRPCServer\")","title":"Installation"},{"category":"section","location":"#License","page":"Home","text":"gRPCServer.jl is licensed under the MIT License — see LICENSE.md.","title":"License"}]
}
